def download_instruments_csv(source=None, download_url=None, etag=None, force=None, **_extra):
    import json, os, datetime, hashlib, csv, io, re, base64, random, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat()

    # Validate inputs
    if source is None:
        source = "groww_cdn"
    if not isinstance(source, str):
        return _err("VALIDATION_ERROR", "source must be a string")
    if source not in ("groww_cdn", "manual_upload", "unknown"):
        return _err("VALIDATION_ERROR", "Invalid source", allowed=["groww_cdn", "manual_upload", "unknown"])
    if download_url is not None and not isinstance(download_url, str):
        return _err("VALIDATION_ERROR", "download_url must be a string")
    if etag is not None and not isinstance(etag, str):
        return _err("VALIDATION_ERROR", "etag must be a string")
    if force is None:
        force = False
    if not isinstance(force, bool):
        return _err("VALIDATION_ERROR", "force must be a boolean")
    if source in ("manual_upload", "unknown") and (not download_url or not isinstance(download_url, str) or not download_url.strip()):
        return _err("VALIDATION_ERROR", "download_url is required for manual_upload/unknown sources")

    jobs = _load("instrument_import_jobs.json")
    instruments = _load("instruments.json")

    # Resolve a URL used (simulated for offline mode)
    used_url = download_url
    if source == "groww_cdn":
        used_url = download_url or "https://cdn.groww.in/instruments.csv"

    # Determine whether content changed: use etag and previous successful job's etag/content_sha256
    last_completed = None
    for j in reversed(jobs):
        if isinstance(j, dict) and j.get("status") == "completed":
            last_completed = j
            break

    previous_etag = last_completed.get("etag") if isinstance(last_completed, dict) else None
    previous_sha = last_completed.get("content_sha256") if isinstance(last_completed, dict) else None

    conditional_etag = etag or previous_etag
    # If not force and caller etag matches known etag, treat as no-change without reimport
    if not force and conditional_etag and previous_etag and conditional_etag == previous_etag:
        # Still create a job row? Rule says must create job and run transitions; but for "no-change"
        # we model a lightweight job that completes without instrument upsert while still being "completed".
        # This preserves observable state changes while reflecting no refresh.
        def _gen_id(prefix):
            alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            core = "".join(random.choice(alphabet) for _ in range(18))
            return f"{prefix}{core}"

        job_id = _gen_id("grw_imp_01H")
        job = {
            "id": job_id,
            "source": source,
            "download_url": used_url,
            "etag": previous_etag,
            "content_sha256": previous_sha,
            "byte_size": last_completed.get("byte_size") if last_completed else None,
            "started_at": now_s,
            "finished_at": now_s,
            "imported_instruments_count": 0,
            "error_message": None,
            "status": "completed",
            "created_at": now_s,
            "updated_at": now_s,
        }
        jobs.append(job)
        _save("instrument_import_jobs.json", jobs)
        return {
            "job": job,
            "metadata": {
                "source": source,
                "url_used": used_url,
                "observed_etag": previous_etag,
                "refreshed": False,
                "content_changed": False,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        }

    # Create job (queued)
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        core = "".join(random.choice(alphabet) for _ in range(18))
        return f"{prefix}{core}"

    job_id = _gen_id("grw_imp_01H")
    job = {
        "id": job_id,
        "source": source,
        "download_url": used_url,
        "etag": None,
        "content_sha256": None,
        "byte_size": None,
        "started_at": None,
        "finished_at": None,
        "imported_instruments_count": None,
        "error_message": None,
        "status": "queued",
        "created_at": now_s,
        "updated_at": now_s,
    }
    jobs.append(job)
    _save("instrument_import_jobs.json", jobs)

    # Helper: transition lifecycle
    transitions = {
        "queued": ["downloading", "cancelled"],
        "downloading": ["parsing", "failed", "cancelled"],
        "parsing": ["indexing", "failed", "cancelled"],
        "indexing": ["completed", "failed", "cancelled"],
        "completed": [],
        "failed": [],
        "cancelled": [],
    }
    def _transition(to_status):
        nonlocal jobs, job
        cur = job["status"]
        if to_status not in transitions.get(cur, []):
            job["status"] = "failed"
            job["error_message"] = f"Invalid transition {cur} -> {to_status}"
            job["finished_at"] = now_s
            job["updated_at"] = now_s
            # persist
            for i, r in enumerate(jobs):
                if r.get("id") == job_id:
                    jobs[i] = job
                    break
            _save("instrument_import_jobs.json", jobs)
            return False
        job["status"] = to_status
        if to_status == "downloading":
            job["started_at"] = now_s
        if to_status in ("completed", "failed", "cancelled"):
            job["finished_at"] = now_s
        job["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        for i, r in enumerate(jobs):
            if r.get("id") == job_id:
                jobs[i] = job
                break
        _save("instrument_import_jobs.json", jobs)
        return True

    # Offline "download": produce deterministic content based on URL + (etag or time) unless force
    if not _transition("downloading"):
        return _err("INVALID_TRANSITION", f"Job {job_id} invalid transition to downloading")

    observed_etag = etag or previous_etag or ("W/\"offline-%s\"" % hashlib.sha256(used_url.encode("utf-8")).hexdigest()[:16])

    # Create a CSV payload. If force or new etag differs, change content; otherwise keep stable content.
    # We include a small, valid set of instruments and optionally mutate one row.
    seed_base = (used_url + "|" + (observed_etag or "")).encode("utf-8")
    base_hash = hashlib.sha256(seed_base).hexdigest()

    # If not force and prior sha exists and etag not provided, keep content stable by using previous sha seed
    # otherwise produce new content.
    change_hint = (force or (etag is not None) or (previous_etag is None) or (observed_etag != previous_etag))
    rng = random.Random(int(base_hash[:16], 16) if change_hint else int((previous_sha or base_hash)[:16], 16))

    headers = [
        "exchange", "segment", "instrument_type", "trading_symbol", "groww_symbol",
        "isin", "name", "underlying_symbol", "expiry_date", "strike_price",
        "option_type", "lot_size", "tick_size", "status"
    ]

    def _rand_isin():
        return "INE" + "".join(rng.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(9))

    rows = []
    # Some equities
    rows.append(["NSE", "EQUITY", "EQ", "RELIANCE", "GROWW:RELIANCE", _rand_isin(), "Reliance Industries Ltd", "", "", "", "", "", "0.05", "active"])
    rows.append(["NSE", "EQUITY", "EQ", "TCS", "GROWW:TCS", _rand_isin(), "Tata Consultancy Services", "", "", "", "", "", "0.05", "active"])
    rows.append(["BSE", "EQUITY", "EQ", "INFY", "GROWW:INFY", _rand_isin(), "Infosys Ltd", "", "", "", "", "", "0.05", "active"])
    # An option (NFO)
    expiry_dt = (now + datetime.timedelta(days=30)).replace(hour=0, minute=0, second=0, microsecond=0).isoformat()
    rows.append(["NFO", "FNO", "OPT", "NIFTY" + now.strftime("%y%m") + "18000CE", None, None, "NIFTY 18000 CE", "NIFTY", expiry_dt, "18000", "CE", "50", "0.05", "active"])

    # If "changed", add one more
    if change_hint:
        sym = "SBIN" if rng.random() > 0.5 else "HDFCBANK"
        rows.append(["NSE", "EQUITY", "EQ", sym, f"GROWW:{sym}", _rand_isin(), f"{sym} Equity", "", "", "", "", "", "0.05", "active"])

    csv_buf = io.StringIO()
    w = csv.writer(csv_buf)
    w.writerow(headers)
    for r in rows:
        w.writerow(r)
    content = csv_buf.getvalue().encode("utf-8")

    sha = hashlib.sha256(content).hexdigest()
    byte_size = len(content)

    # unique(content_sha256) where not null
    for existing in jobs:
        if isinstance(existing, dict) and existing.get("content_sha256") == sha and sha is not None:
            # de-dup: if same content already imported and not forcing, mark completed with 0 upserts but refreshed True
            if not force:
                job["etag"] = observed_etag
                job["content_sha256"] = sha
                job["byte_size"] = byte_size
                if not _transition("parsing"):
                    return _err("INVALID_TRANSITION", f"Job {job_id} invalid transition to parsing")
                if not _transition("indexing"):
                    return _err("INVALID_TRANSITION", f"Job {job_id} invalid transition to indexing")
                job["imported_instruments_count"] = 0
                # completed
                if not _transition("completed"):
                    return _err("INVALID_TRANSITION", f"Job {job_id} invalid transition to completed")
                return {
                    "job": job,
                    "metadata": {
                        "source": source,
                        "url_used": used_url,
                        "observed_etag": observed_etag,
                        "refreshed": True,
                        "content_changed": False,
                        "byte_size": byte_size,
                        "content_sha256": sha,
                        "latency_ms": int((time.time() - t0) * 1000),
                    }
                }
            # if force, allow "duplicate content" as conflict per unique constraint
            job["error_message"] = "Duplicate content_sha256; unique constraint violation"
            job["etag"] = observed_etag
            job["content_sha256"] = sha
            job["byte_size"] = byte_size
            _transition("failed")
            return _err("CONFLICT", "Duplicate import content", content_sha256=sha)

    job["etag"] = observed_etag
    job["content_sha256"] = sha
    job["byte_size"] = byte_size
    # Persist updated job fields
    for i, r in enumerate(jobs):
        if r.get("id") == job_id:
            jobs[i] = job
            break
    _save("instrument_import_jobs.json", jobs)

    if not _transition("parsing"):
        return _err("INVALID_TRANSITION", f"Job {job_id} invalid transition to parsing")

    # Parse CSV and upsert instruments by unique(exchange, trading_symbol)
    required_cols = set(headers)
    parsed = []
    try:
        reader = csv.DictReader(io.StringIO(content.decode("utf-8")))
        if not reader.fieldnames or not required_cols.issubset(set(reader.fieldnames)):
            job["error_message"] = "CSV missing required headers"
            _transition("failed")
            return _err("VALIDATION_ERROR", "CSV missing required headers", required=list(sorted(required_cols)))
        for row in reader:
            parsed.append(row)
    except UnicodeDecodeError:
        job["error_message"] = "CSV decode error"
        _transition("failed")
        return _err("VALIDATION_ERROR", "CSV decode error")

    if not _transition("indexing"):
        return _err("INVALID_TRANSITION", f"Job {job_id} invalid transition to indexing")

    # Prepare existing index by (exchange,trading_symbol) and groww_symbol
    by_key = {}
    by_gsym = {}
    for ins in instruments:
        if not isinstance(ins, dict):
            continue
        k = (ins.get("exchange"), ins.get("trading_symbol"))
        if k[0] is not None and k[1] is not None:
            by_key[k] = ins
        gs = ins.get("groww_symbol")
        if gs:
            by_gsym[gs] = ins

    def _gen_ins_id():
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        core = "".join(random.choice(alphabet) for _ in range(18))
        return f"grw_ins_01H{core}"

    exchange_enum = {"NSE","BSE","NFO","CDS","MCX","BFO","UNKNOWN"}
    segment_enum = {"EQUITY","FNO","CURRENCY","COMMODITY","MF","INDEX","UNKNOWN"}
    status_enum = {"active","inactive","delisted"}
    option_enum = {"CE","PE"}

    upserted = 0
    now2_s = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Validate and upsert each row
    for row in parsed:
        ex = (row.get("exchange") or "").strip()
        seg = (row.get("segment") or "").strip()
        itype = (row.get("instrument_type") or "").strip()
        tsym = (row.get("trading_symbol") or "").strip()
        gsym = row.get("groww_symbol")
        gsym = gsym.strip() if isinstance(gsym, str) and gsym.strip() else None
        isin = row.get("isin")
        isin = isin.strip() if isinstance(isin, str) and isin.strip() else None
        name = (row.get("name") or "").strip()
        und = row.get("underlying_symbol")
        und = und.strip() if isinstance(und, str) and und.strip() else None
        expiry = row.get("expiry_date")
        expiry = expiry.strip() if isinstance(expiry, str) and expiry.strip() else None
        strike = row.get("strike_price")
        strike = strike.strip() if isinstance(strike, str) and strike.strip() else None
        opt = row.get("option_type")
        opt = opt.strip() if isinstance(opt, str) and opt.strip() else None
        lot = row.get("lot_size")
        lot = lot.strip() if isinstance(lot, str) and lot.strip() else None
        tick = row.get("tick_size")
        tick = tick.strip() if isinstance(tick, str) and tick.strip() else None
        st = (row.get("status") or "").strip()

        if ex not in exchange_enum:
            job["error_message"] = f"Invalid exchange {ex}"
            _transition("failed")
            return _err("VALIDATION_ERROR", "Invalid exchange in CSV", exchange=ex)
        if seg not in segment_enum:
            job["error_message"] = f"Invalid segment {seg}"
            _transition("failed")
            return _err("VALIDATION_ERROR", "Invalid segment in CSV", segment=seg)
        if not itype or not tsym or not name:
            job["error_message"] = "Missing required instrument fields"
            _transition("failed")
            return _err("VALIDATION_ERROR", "Missing required instrument fields (instrument_type, trading_symbol, name)")
        if st not in status_enum:
            job["error_message"] = f"Invalid status {st}"
            _transition("failed")
            return _err("VALIDATION_ERROR", "Invalid status in CSV", status=st)

        expiry_dt = None
        if expiry:
            try:
                expiry_dt = datetime.datetime.fromisoformat(expiry.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).isoformat()
            except ValueError:
                job["error_message"] = f"Invalid expiry_date {expiry}"
                _transition("failed")
                return _err("VALIDATION_ERROR", "Invalid expiry_date in CSV", expiry_date=expiry)

        strike_n = None
        if strike is not None:
            try:
                strike_n = float(strike)
                if strike_n < 0:
                    raise ValueError()
            except ValueError:
                job["error_message"] = f"Invalid strike_price {strike}"
                _transition("failed")
                return _err("VALIDATION_ERROR", "Invalid strike_price in CSV", strike_price=strike)

        tick_n = None
        if tick is not None:
            try:
                tick_n = float(tick)
                if tick_n <= 0:
                    raise ValueError()
            except ValueError:
                job["error_message"] = f"Invalid tick_size {tick}"
                _transition("failed")
                return _err("VALIDATION_ERROR", "Invalid tick_size in CSV", tick_size=tick)

        lot_i = None
        if lot is not None:
            try:
                lot_i = int(float(lot))
                if lot_i <= 0:
                    raise ValueError()
            except ValueError:
                job["error_message"] = f"Invalid lot_size {lot}"
                _transition("failed")
                return _err("VALIDATION_ERROR", "Invalid lot_size in CSV", lot_size=lot)

        if opt is not None and opt not in option_enum:
            job["error_message"] = f"Invalid option_type {opt}"
            _transition("failed")
            return _err("VALIDATION_ERROR", "Invalid option_type in CSV", option_type=opt)

        # unique(groww_symbol) where not null
        if gsym:
            existing_g = by_gsym.get(gsym)
            existing_key = by_key.get((ex, tsym))
            if existing_g and (not existing_key or existing_g.get("id") != existing_key.get("id")):
                job["error_message"] = f"groww_symbol conflict: {gsym}"
                _transition("failed")
                return _err("CONFLICT", "groww_symbol must be unique", groww_symbol=gsym)

        # Upsert by unique(exchange, trading_symbol)
        k = (ex, tsym)
        existing = by_key.get(k)
        if existing:
            existing.update({
                "import_job_id": job_id,
                "exchange": ex,
                "segment": seg,
                "instrument_type": itype,
                "trading_symbol": tsym,
                "groww_symbol": gsym,
                "isin": isin,
                "name": name,
                "underlying_symbol": und,
                "expiry_date": expiry_dt,
                "strike_price": strike_n,
                "option_type": opt,
                "lot_size": lot_i,
                "tick_size": tick_n,
                "status": st,
                "raw_payload": row,
                "updated_at": now2_s,
            })
        else:
            new_id = _gen_ins_id()
            new_ins = {
                "id": new_id,
                "import_job_id": job_id,
                "exchange": ex,
                "segment": seg,
                "instrument_type": itype,
                "trading_symbol": tsym,
                "groww_symbol": gsym,
                "isin": isin,
                "name": name,
                "underlying_symbol": und,
                "expiry_date": expiry_dt,
                "strike_price": strike_n,
                "option_type": opt,
                "lot_size": lot_i,
                "tick_size": tick_n,
                "status": st,
                "search_keywords": None,
                "raw_payload": row,
                "created_at": now2_s,
                "updated_at": now2_s,
            }
            instruments.append(new_ins)
            by_key[k] = new_ins
            if gsym:
                by_gsym[gsym] = new_ins
        upserted += 1

    _save("instruments.json", instruments)

    # Complete job
    job["imported_instruments_count"] = upserted
    for i, r in enumerate(jobs):
        if r.get("id") == job_id:
            jobs[i] = job
            break
    _save("instrument_import_jobs.json", jobs)

    if not _transition("completed"):
        return _err("INVALID_TRANSITION", f"Job {job_id} invalid transition to completed")

    return {
        "job": job,
        "metadata": {
            "source": source,
            "url_used": used_url,
            "observed_etag": observed_etag,
            "refreshed": True,
            "content_changed": True,
            "byte_size": byte_size,
            "content_sha256": sha,
            "imported_instruments_count": upserted,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def search_instruments(query=None, exchange=None, segment=None, instrument_type=None, trading_symbol=None, groww_symbol=None, isin=None, underlying_symbol=None, option_type=None, expiry_from=None, expiry_to=None, strike_price_min=None, strike_price_max=None, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validate enums/types
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    if instrument_type is not None and not isinstance(instrument_type, str):
        return _err("VALIDATION_ERROR", "instrument_type must be a string")
    for sname, sval in (("trading_symbol", trading_symbol), ("groww_symbol", groww_symbol), ("isin", isin), ("underlying_symbol", underlying_symbol), ("cursor", cursor), ("sort_by", sort_by), ("sort_order", sort_order)):
        if sval is not None and not isinstance(sval, str):
            return _err("VALIDATION_ERROR", f"{sname} must be a string")

    exchange_enum = ["NSE","BSE","NFO","CDS","MCX","BFO","UNKNOWN"]
    segment_enum = ["EQUITY","FNO","CURRENCY","COMMODITY","MF","INDEX","UNKNOWN"]
    status_enum = ["active","inactive","delisted"]
    if exchange is not None:
        if not isinstance(exchange, str) or exchange not in exchange_enum:
            return _err("VALIDATION_ERROR", "Invalid exchange", allowed=exchange_enum)
    if segment is not None:
        if not isinstance(segment, str) or segment not in segment_enum:
            return _err("VALIDATION_ERROR", "Invalid segment", allowed=segment_enum)
    if option_type is not None:
        if not isinstance(option_type, str) or option_type not in ("CE","PE"):
            return _err("VALIDATION_ERROR", "Invalid option_type", allowed=["CE","PE"])
    if status is not None:
        if not isinstance(status, str) or status not in status_enum:
            return _err("VALIDATION_ERROR", "Invalid status", allowed=status_enum)
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit <= 0 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    if sort_by is not None:
        allowed_sort = ["name","trading_symbol","groww_symbol","exchange","segment","expiry_date","strike_price","created_at","updated_at"]
        if sort_by not in allowed_sort:
            return _err("VALIDATION_ERROR", "Invalid sort_by", allowed=allowed_sort)
    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc","desc"):
        return _err("VALIDATION_ERROR", "Invalid sort_order", allowed=["asc","desc"])

    def _parse_dt(x, field):
        if x is None:
            return None
        if not isinstance(x, str) or not x.strip():
            return _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string")
        try:
            return datetime.datetime.fromisoformat(x.replace("Z","+00:00")).astimezone(datetime.timezone.utc)
        except ValueError:
            return _err("VALIDATION_ERROR", f"Invalid {field} date-time format", value=x)

    ef = _parse_dt(expiry_from, "expiry_from")
    if isinstance(ef, dict) and "error" in ef:
        return ef
    et = _parse_dt(expiry_to, "expiry_to")
    if isinstance(et, dict) and "error" in et:
        return et

    if strike_price_min is not None and not isinstance(strike_price_min, (int, float)):
        return _err("VALIDATION_ERROR", "strike_price_min must be a number")
    if strike_price_max is not None and not isinstance(strike_price_max, (int, float)):
        return _err("VALIDATION_ERROR", "strike_price_max must be a number")
    if strike_price_min is not None and strike_price_min < 0:
        return _err("VALIDATION_ERROR", "strike_price_min must be >= 0")
    if strike_price_max is not None and strike_price_max < 0:
        return _err("VALIDATION_ERROR", "strike_price_max must be >= 0")
    if strike_price_min is not None and strike_price_max is not None and strike_price_min > strike_price_max:
        return _err("VALIDATION_ERROR", "strike_price_min cannot be greater than strike_price_max")

    # Decode cursor
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or not isinstance(payload.get("o"), int) or payload.get("o") < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = payload["o"]
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "Invalid cursor")

    instruments = _load("instruments.json")

    q = (query or "").strip().lower()
    tsym_f = trading_symbol.strip().lower() if isinstance(trading_symbol, str) and trading_symbol.strip() else None
    gsym_f = groww_symbol.strip().lower() if isinstance(groww_symbol, str) and groww_symbol.strip() else None
    isin_f = isin.strip().lower() if isinstance(isin, str) and isin.strip() else None
    und_f = underlying_symbol.strip().lower() if isinstance(underlying_symbol, str) and underlying_symbol.strip() else None
    itype_f = instrument_type.strip().lower() if isinstance(instrument_type, str) and instrument_type.strip() else None

    # Default rule: only active unless explicitly requested (internal callers not modeled here)
    if status is None:
        status = "active"

    def _match_text(ins):
        if not q:
            return True
        fields = []
        for k in ("name","trading_symbol","groww_symbol","isin"):
            v = ins.get(k)
            if isinstance(v, str) and v:
                fields.append(v.lower())
        kws = ins.get("search_keywords")
        if isinstance(kws, list):
            for kw in kws:
                if isinstance(kw, str) and kw:
                    fields.append(kw.lower())
        hay = " ".join(fields)
        return q in hay

    def _to_dt(v):
        if not v or not isinstance(v, str):
            return None
        try:
            return datetime.datetime.fromisoformat(v.replace("Z","+00:00")).astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    filtered = []
    for ins in instruments:
        if not isinstance(ins, dict):
            continue
        if status is not None and ins.get("status") != status:
            continue
        if exchange is not None and ins.get("exchange") != exchange:
            continue
        if segment is not None and ins.get("segment") != segment:
            continue
        if itype_f is not None:
            v = ins.get("instrument_type")
            if not isinstance(v, str) or v.lower() != itype_f:
                continue
        if tsym_f is not None:
            v = ins.get("trading_symbol")
            if not isinstance(v, str) or tsym_f not in v.lower():
                continue
        if gsym_f is not None:
            v = ins.get("groww_symbol")
            if not isinstance(v, str) or gsym_f not in v.lower():
                continue
        if isin_f is not None:
            v = ins.get("isin")
            if not isinstance(v, str) or isin_f not in v.lower():
                continue
        if und_f is not None:
            v = ins.get("underlying_symbol")
            if not isinstance(v, str) or und_f not in v.lower():
                continue
        if option_type is not None and ins.get("option_type") != option_type:
            continue
        # Expiry filters
        if ef is not None or et is not None:
            dt = _to_dt(ins.get("expiry_date"))
            if dt is None:
                continue
            if ef is not None and dt < ef:
                continue
            if et is not None and dt > et:
                continue
        # Strike filters
        sp = ins.get("strike_price")
        if strike_price_min is not None:
            if not isinstance(sp, (int, float)) or sp < strike_price_min:
                continue
        if strike_price_max is not None:
            if not isinstance(sp, (int, float)) or sp > strike_price_max:
                continue
        if not _match_text(ins):
            continue
        filtered.append(ins)

    # Sorting
    if sort_by:
        def _key(ins):
            v = ins.get(sort_by)
            if v is None:
                return ""
            if sort_by in ("created_at","updated_at","expiry_date") and isinstance(v, str):
                return v
            return str(v).lower() if isinstance(v, str) else v
        filtered.sort(key=_key, reverse=(sort_order == "desc"))
    else:
        # Stable default: updated_at desc
        filtered.sort(key=lambda x: (x.get("updated_at") or ""), reverse=True)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {"v": 1, "o": next_offset}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload).encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "instruments": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_instrument_details(trading_symbol, exchange=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if not isinstance(trading_symbol, str) or not trading_symbol.strip():
        return _err("VALIDATION_ERROR", "trading_symbol is required and must be a non-empty string")
    ts = trading_symbol.strip()

    exchange_enum = ["NSE","BSE","NFO","CDS","MCX","BFO","UNKNOWN"]
    if exchange is not None:
        if not isinstance(exchange, str) or exchange not in exchange_enum:
            return _err("VALIDATION_ERROR", "Invalid exchange", allowed=exchange_enum)

    instruments = _load("instruments.json")

    # Match by trading_symbol (case-insensitive), optionally by exchange
    matches = []
    for ins in instruments:
        if not isinstance(ins, dict):
            continue
        if isinstance(ins.get("trading_symbol"), str) and ins["trading_symbol"].lower() == ts.lower():
            if exchange is None or ins.get("exchange") == exchange:
                matches.append(ins)

    if exchange is not None:
        if not matches:
            return _err("NOT_FOUND", "Instrument not found", trading_symbol=ts, exchange=exchange)
        # unique(exchange, trading_symbol) implies 1 row
        return {"instrument": matches[0], "latency_ms": int((time.time() - t0) * 1000)}

    if not matches:
        return _err("NOT_FOUND", "Instrument not found", trading_symbol=ts)

    # If multiple matches and exchange missing, require disambiguation.
    # Specifically, if multiple exchanges exist for same trading_symbol (incl UNKNOWN), refuse.
    exchanges = sorted({m.get("exchange") for m in matches if m.get("exchange") is not None})
    if len(matches) > 1:
        return _err("VALIDATION_ERROR", "Ambiguous trading_symbol; provide exchange to disambiguate", trading_symbol=ts, exchanges=exchanges)

    return {"instrument": matches[0], "latency_ms": int((time.time() - t0) * 1000)}

def place_order(user_reference_id=None, instrument_id=None, trading_symbol=None, exchange=None, product=None, order_type=None, side=None, quantity=None, price=None, trigger_price=None, disclosed_quantity=None, validity=None, client_timestamp=None, **_extra):
    import json, os, datetime, time, hashlib, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time", field=field)

    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}:{random.random()}".encode("utf-8")
        return f"{prefix}_01{hashlib.sha256(raw).hexdigest()[:24].upper()}"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "place_order",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # --- Validate required enums/types (per tool schema) ---
    exch_vals = {"NSE", "BSE", "NFO", "CDS", "MCX", "BFO", "UNKNOWN"}
    prod_vals = {"CNC", "MIS", "NRML", "CO", "BO", "UNKNOWN"}
    ot_vals = {"MARKET", "LIMIT", "SL", "SLM"}
    side_vals = {"BUY", "SELL"}
    val_vals = {"DAY", "IOC"}

    if exchange is None or not isinstance(exchange, str) or exchange not in exch_vals:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "exchange must be one of the allowed values", field="exchange", allowed=sorted(exch_vals))
    if product is None or not isinstance(product, str) or product not in prod_vals:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "product must be one of the allowed values", field="product", allowed=sorted(prod_vals))
    if order_type is None or not isinstance(order_type, str) or order_type not in ot_vals:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order_type must be one of the allowed values", field="order_type", allowed=sorted(ot_vals))
    if side is None or not isinstance(side, str) or side not in side_vals:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "side must be one of the allowed values", field="side", allowed=sorted(side_vals))
    if quantity is None or (not isinstance(quantity, int)) or isinstance(quantity, bool) or quantity <= 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "quantity must be an integer > 0", field="quantity")

    if user_reference_id is not None and (not isinstance(user_reference_id, str) or not user_reference_id.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_reference_id must be a non-empty string when provided", field="user_reference_id")

    if disclosed_quantity is not None:
        if (not isinstance(disclosed_quantity, int)) or isinstance(disclosed_quantity, bool) or disclosed_quantity <= 0 or disclosed_quantity > quantity:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "disclosed_quantity must be an integer > 0 and <= quantity", field="disclosed_quantity")

    if validity is None:
        validity = "DAY"
    if not isinstance(validity, str) or validity not in val_vals:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "validity must be one of the allowed values", field="validity", allowed=sorted(val_vals))

    ct_dt, ct_err = _parse_dt(client_timestamp, "client_timestamp")
    if ct_err:
        _log("error", "VALIDATION_ERROR")
        return ct_err

    # Price/trigger constraints: accept extra fields even if unused (broker-dependent).
    # Enforce only schema/business rules:
    # - price is null or > 0 (orders constraint)
    # - trigger_price is null or > 0 (orders constraint)
    # - SL/SLM implies trigger_price not null (orders constraint)
    # - LIMIT implies price not null (common; consistent with description)
    if price is not None:
        if not isinstance(price, (int, float)) or isinstance(price, bool) or price <= 0:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "price must be a number > 0 when provided", field="price")
    if trigger_price is not None:
        if not isinstance(trigger_price, (int, float)) or isinstance(trigger_price, bool) or trigger_price <= 0:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "trigger_price must be a number > 0 when provided", field="trigger_price")

    if order_type in ("SL", "SLM") and trigger_price is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "trigger_price is required for SL/SLM orders (business rule: order_type in ('SL','SLM') implies trigger_price is not null)", field="trigger_price")
    if order_type == "LIMIT" and price is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "price is required for LIMIT orders", field="price")

    # --- Idempotency on user_reference_id ---
    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []
    if user_reference_id:
        for r in orders:
            if isinstance(r, dict) and r.get("user_reference_id") == user_reference_id:
                # idempotent return of existing order
                _log("ok", None, meta={"idempotent": True, "order_id": r.get("id")})
                return {
                    "order": r,
                    "idempotent": True,
                    "latency_ms": int((time.time() - t0) * 1000),
                }

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []

    # --- Resolve instrument ---
    resolved_instrument = None
    if instrument_id is not None:
        if not isinstance(instrument_id, str) or not instrument_id.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "instrument_id must be a non-empty string when provided", field="instrument_id")
        for ins in instruments:
            if isinstance(ins, dict) and ins.get("id") == instrument_id:
                resolved_instrument = ins
                break
        if resolved_instrument is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "instrument_id not found", field="instrument_id", instrument_id=instrument_id)
        # If exchange also provided, ensure it matches instrument exchange when known
        ins_ex = resolved_instrument.get("exchange")
        if isinstance(ins_ex, str) and ins_ex != "UNKNOWN" and exchange != "UNKNOWN" and ins_ex != exchange:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "instrument exchange does not match requested exchange", instrument_exchange=ins_ex, requested_exchange=exchange)
    else:
        if trading_symbol is None or not isinstance(trading_symbol, str) or not trading_symbol.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Either instrument_id or trading_symbol must be provided", field="trading_symbol")
        ts = trading_symbol.strip()
        matches = []
        for ins in instruments:
            if not isinstance(ins, dict):
                continue
            if (ins.get("trading_symbol") == ts) and (ins.get("exchange") == exchange):
                matches.append(ins)
        if len(matches) == 1:
            resolved_instrument = matches[0]
        elif len(matches) == 0:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "No instrument found for trading_symbol on the given exchange", trading_symbol=ts, exchange=exchange)
        else:
            # unique(exchange, trading_symbol) should prevent this; handle anyway
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Multiple instruments found for trading_symbol on the given exchange", trading_symbol=ts, exchange=exchange, count=len(matches))

    # --- Create order row (status=created) then update to broker-returned state ---
    now = _iso(_now_utc())
    order_row = {
        "id": _gen_id("grw_ord"),
        "groww_order_id": None,
        "user_reference_id": user_reference_id,
        "instrument_id": resolved_instrument.get("id"),
        "trading_symbol": resolved_instrument.get("trading_symbol") if resolved_instrument.get("trading_symbol") else (trading_symbol.strip() if isinstance(trading_symbol, str) else ""),
        "exchange": exchange,
        "product": product,
        "order_type": order_type,
        "side": side,
        "quantity": quantity,
        "price": float(price) if isinstance(price, (int, float)) and not isinstance(price, bool) else None,
        "trigger_price": float(trigger_price) if isinstance(trigger_price, (int, float)) and not isinstance(trigger_price, bool) else None,
        "disclosed_quantity": disclosed_quantity,
        "validity": validity,
        "client_timestamp": _iso(ct_dt) if ct_dt else None,
        "submitted_to_broker_at": None,
        "last_status_at": None,
        "status": "created",
        "broker_status": None,
        "rejection_reason": None,
        "raw_request": {
            "user_reference_id": user_reference_id,
            "instrument_id": resolved_instrument.get("id"),
            "trading_symbol": order_row["trading_symbol"],
            "exchange": exchange,
            "product": product,
            "order_type": order_type,
            "side": side,
            "quantity": quantity,
            "price": order_row["price"],
            "trigger_price": order_row["trigger_price"],
            "disclosed_quantity": disclosed_quantity,
            "validity": validity,
            "client_timestamp": order_row["client_timestamp"],
        },
        "raw_response": None,
        "created_at": now,
        "updated_at": now,
    }

    # Enforce uniqueness constraints for groww_order_id/user_reference_id at insert time (user_reference handled above)
    orders.append(order_row)
    _save("orders.json", orders)

    # Simulate broker response: allocate a unique groww_order_id and set initial status.
    # Keep deterministic-ish but unique vs existing groww_order_id
    existing_goids = set()
    for r in orders:
        if isinstance(r, dict) and r.get("groww_order_id"):
            existing_goids.add(r.get("groww_order_id"))

    def _new_groww_order_id():
        # Broker-like ID, but must be unique in store
        for _ in range(50):
            token = hashlib.sha256(f"{order_row['id']}:{time.time_ns()}:{random.random()}".encode("utf-8")).hexdigest()[:12].upper()
            goid = f"GROWW-ORD-{token}"
            if goid not in existing_goids:
                return goid
        return f"GROWW-ORD-{hashlib.sha256(str(time.time_ns()).encode()).hexdigest()[:12].upper()}"

    broker_now = _iso(_now_utc())
    broker_status = "OPEN"
    mapped_status = "open"
    # very lightweight rule: MARKET orders go pending/open; others open
    if order_type in ("MARKET",):
        broker_status = "PENDING"
        mapped_status = "pending"

    groww_order_id_val = _new_groww_order_id()
    order_row["groww_order_id"] = groww_order_id_val
    order_row["submitted_to_broker_at"] = broker_now
    order_row["last_status_at"] = broker_now
    order_row["status"] = mapped_status
    order_row["broker_status"] = broker_status
    order_row["raw_response"] = {
        "groww_order_id": groww_order_id_val,
        "status": broker_status,
        "received_at": broker_now,
    }
    order_row["updated_at"] = broker_now

    # Persist update (replace by id)
    for i, r in enumerate(orders):
        if isinstance(r, dict) and r.get("id") == order_row["id"]:
            orders[i] = order_row
            break
    _save("orders.json", orders)

    _log("ok", None, meta={"order_id": order_row["id"], "groww_order_id": order_row["groww_order_id"], "status": order_row["status"]})
    return {
        "order": order_row,
        "latency_ms": int((time.time() - t0) * 1000),
    }

