            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "disclosed_quantity must be an integer > 0 when provided", field="disclosed_quantity")
    if validity is not None:
        if not isinstance(validity, str) or validity not in ("DAY", "IOC"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "validity must be one of: DAY, IOC", field="validity")

    ct_dt, ct_err = _parse_dt(client_timestamp, "client_timestamp")
    if ct_err:
        _log("error", "VALIDATION_ERROR")
        return ct_err

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []
    order = None
    idx = None
    for i, r in enumerate(orders):
        if not isinstance(r, dict):
            continue
        if order_id is not None and r.get("id") == order_id:
            order = r
            idx = i
            break
        if order is None and groww_order_id is not None and r.get("groww_order_id") == groww_order_id:
            order = r
            idx = i
            break
    if order is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Order not found", order_id=order_id, groww_order_id=groww_order_id)

    if order_id is not None and groww_order_id is not None and order.get("groww_order_id") and order.get("groww_order_id") != groww_order_id:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "order_id and groww_order_id refer to different orders")

    # Business rule: only modifiable states
    if order.get("status") not in ("pending", "open", "partially_filled"):
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "modify_order is only allowed when orders.status in ('pending','open','partially_filled')", current_status=order.get("status"))

    # Do not reduce quantity below filled quantity (derived from trades)
    trades = _load("trades.json")
    if not isinstance(trades, list):
        trades = []
    filled_qty = 0
    for tr in trades:
        if not isinstance(tr, dict):
            continue
        if tr.get("order_id") != order.get("id"):
            continue
        if tr.get("status") in ("reported", "corrected"):
            fq = tr.get("fill_quantity")
            if isinstance(fq, int) and not isinstance(fq, bool) and fq > 0:
                filled_qty += fq
    if quantity is not None and quantity < filled_qty:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Cannot reduce quantity below total filled quantity (business rule)", field="quantity", requested=quantity, filled_quantity=filled_qty)

    # Validate disclosed_quantity relative to (potentially updated) quantity
    new_qty = quantity if quantity is not None else order.get("quantity")
    if disclosed_quantity is not None and new_qty is not None:
        if disclosed_quantity > new_qty:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "disclosed_quantity must be <= quantity", field="disclosed_quantity", quantity=new_qty)

    # Validate trigger requirement for SL/SLM if being modified in a way that would violate constraints
    ot = order.get("order_type")
    new_trigger = trigger_price if trigger_price is not None else order.get("trigger_price")
    new_price = float(price) if price is not None else order.get("price")
    if ot in ("SL", "SLM") and new_trigger is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "trigger_price is required for SL/SLM orders (business rule)", field="trigger_price")
    if ot == "LIMIT" and new_price is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "price is required for LIMIT orders", field="price")

    # Apply modifications
    now = _iso(_now_utc())
    if quantity is not None:
        order["quantity"] = quantity
    if price is not None:
        order["price"] = float(price)
    if trigger_price is not None:
        order["trigger_price"] = float(trigger_price)
    if disclosed_quantity is not None:
        order["disclosed_quantity"] = disclosed_quantity
    if validity is not None:
        order["validity"] = validity
    if ct_dt is not None:
        order["client_timestamp"] = _iso(ct_dt)

    # Update raw_request/raw_response and updated_at (business rule)
    req = {
        "action": "modify",
        "order_id": order.get("id"),
        "groww_order_id": order.get("groww_order_id"),
        "quantity": order.get("quantity"),
        "price": order.get("price"),
        "trigger_price": order.get("trigger_price"),
        "disclosed_quantity": order.get("disclosed_quantity"),
        "validity": order.get("validity"),
        "client_timestamp": order.get("client_timestamp"),
    }
    order["raw_request"] = req
    order["raw_response"] = {
        "status": "OK",
        "updated_fields": [k for k in ("quantity", "price", "trigger_price", "disclosed_quantity", "validity", "client_timestamp") if locals().get(k) is not None],
        "received_at": now
    }
    order["updated_at"] = now

    orders[idx] = order
    _save("orders.json", orders)

    _log("ok", None, meta={"order_id": order.get("id"), "groww_order_id": order.get("groww_order_id")})
    return {"order": order, "latency_ms": int((time.time() - t0) * 1000)}

def cancel_order(groww_order_id=None, order_id=None, client_timestamp=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time")

    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}".encode("utf-8")
        h = hashlib.sha256(raw).hexdigest()[:26].upper()
        return f"{prefix}_{h}"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "cancel_order",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate identifiers: require at least one
    if (groww_order_id is None or (isinstance(groww_order_id, str) and groww_order_id.strip() == "")) and \
       (order_id is None or (isinstance(order_id, str) and order_id.strip() == "")):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either groww_order_id or order_id must be provided.")

    if groww_order_id is not None and not isinstance(groww_order_id, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "groww_order_id must be a string.")

    # IMPORTANT: do not reject real datastore ids; pattern in schema is too strict vs existing data.
    if order_id is not None and not isinstance(order_id, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order_id must be a string.")

    ct, e = _parse_dt(client_timestamp, "client_timestamp")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []

    # Resolve order (prefer order_id if provided)
    matches = []
    if isinstance(order_id, str) and order_id.strip():
        oid = order_id.strip()
        matches = [o for o in orders if isinstance(o, dict) and o.get("id") == oid]
    if not matches and isinstance(groww_order_id, str) and groww_order_id.strip():
        gid = groww_order_id.strip()
        matches = [o for o in orders if isinstance(o, dict) and o.get("groww_order_id") == gid]

    if not matches:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Order not found")

    # Uniqueness should hold but don't cancel ambiguously
    if len(matches) > 1:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Multiple orders matched identifier; cannot cancel safely")

    order = matches[0]
    current_status = order.get("status")

    cancellable = {"pending", "open", "partially_filled"}
    terminal = {"filled", "cancelled", "rejected", "expired", "failed"}
    if current_status in terminal or current_status not in cancellable:
        _log("error", "CONFLICT", {"current_status": current_status})
        return _err("CONFLICT", "Order is already terminal or not cancellable", current_status=current_status)

    # Perform lifecycle transition to cancelled (default success path)
    now = _iso(_now_utc())
    order["raw_request"] = {
        "action": "cancel",
        "groww_order_id": order.get("groww_order_id"),
        "order_id": order.get("id"),
        "client_timestamp": _iso(ct) if ct else client_timestamp
    }

    # Simulated broker outcome: accept cancellation
    order["status"] = "cancelled"
    order["broker_status"] = "CANCELLED"
    order["rejection_reason"] = None
    order["last_status_at"] = now
    order["updated_at"] = now
    order["raw_response"] = {
        "ok": True,
        "action": "cancel",
        "groww_order_id": order.get("groww_order_id"),
        "status": order["status"],
        "broker_status": order["broker_status"],
        "timestamp": now
    }

    _save("orders.json", orders)
    _log("success")
    return {"order": order}

