def get_order_list(from_ts=None, to_ts=None, status=None, exchange=None, product=None, side=None, instrument_id=None, trading_symbol=None, user_reference_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string")
        try:
            # accept trailing Z
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time")

    def _dt_from_row(v):
        if not v:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            try:
                ss = v[:-1] + "+00:00" if v.endswith("Z") else v
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    def _log(endpoint, status_code, detail=None):
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "status": status_code,
            "detail": detail,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso(),
        }
        fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save(fname, logs)

    # Validation
    enums_status = {"created", "pending", "open", "partially_filled", "filled", "cancelled", "rejected", "expired", "failed"}
    enums_exchange = {"NSE", "BSE", "NFO", "CDS", "MCX", "BFO", "UNKNOWN"}
    enums_product = {"CNC", "MIS", "NRML", "CO", "BO", "UNKNOWN"}
    enums_side = {"BUY", "SELL"}
    enums_sort_by = {"created_at", "updated_at", "last_status_at", "submitted_to_broker_at"}
    enums_sort_order = {"asc", "desc"}

    if status is not None and status not in enums_status:
        _log("get_order_list", "VALIDATION_ERROR", "bad status")
        return _err("VALIDATION_ERROR", "Invalid status", field="status")
    if exchange is not None and exchange not in enums_exchange:
        _log("get_order_list", "VALIDATION_ERROR", "bad exchange")
        return _err("VALIDATION_ERROR", "Invalid exchange", field="exchange")
    if product is not None and product not in enums_product:
        _log("get_order_list", "VALIDATION_ERROR", "bad product")
        return _err("VALIDATION_ERROR", "Invalid product", field="product")
    if side is not None and side not in enums_side:
        _log("get_order_list", "VALIDATION_ERROR", "bad side")
        return _err("VALIDATION_ERROR", "Invalid side", field="side")
    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in enums_sort_by:
        _log("get_order_list", "VALIDATION_ERROR", "bad sort_by")
        return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by")
    if sort_order is None:
        sort_order = "desc"
    if sort_order not in enums_sort_order:
        _log("get_order_list", "VALIDATION_ERROR", "bad sort_order")
        return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("get_order_list", "VALIDATION_ERROR", "bad limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    if instrument_id is not None:
        if not isinstance(instrument_id, str) or not re.match(r"^grw_ins_[0-9A-HJKMNP-TV-Z]{16,}$", instrument_id):
            _log("get_order_list", "VALIDATION_ERROR", "bad instrument_id")
            return _err("VALIDATION_ERROR", "Invalid instrument_id format", field="instrument_id")

    dt_from, e = _parse_dt(from_ts, "from_ts")
    if e:
        _log("get_order_list", "VALIDATION_ERROR", "bad from_ts")
        return e
    dt_to, e = _parse_dt(to_ts, "to_ts")
    if e:
        _log("get_order_list", "VALIDATION_ERROR", "bad to_ts")
        return e
    if dt_from and dt_to and dt_from > dt_to:
        _log("get_order_list", "VALIDATION_ERROR", "from_ts > to_ts")
        return _err("VALIDATION_ERROR", "from_ts must be <= to_ts")

    # Cursor parsing (opaque)
    cur = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("get_order_list", "VALIDATION_ERROR", "bad cursor")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cur = json.loads(raw.decode("utf-8"))
            if not isinstance(cur, dict) or "offset" not in cur:
                raise ValueError("bad cursor")
            if not isinstance(cur["offset"], int) or cur["offset"] < 0:
                raise ValueError("bad offset")
            if cur.get("sort_by") != sort_by or cur.get("sort_order") != sort_order:
                _log("get_order_list", "VALIDATION_ERROR", "cursor sort mismatch")
                return _err("VALIDATION_ERROR", "cursor does not match sort parameters")
            # If provided in cursor, enforce same window/filters for consistency.
            for k in ("from_ts", "to_ts", "status", "exchange", "product", "side", "instrument_id", "trading_symbol", "user_reference_id"):
                if k in cur:
                    if locals().get(k) != cur.get(k):
                        _log("get_order_list", "VALIDATION_ERROR", f"cursor filter mismatch {k}")
                        return _err("VALIDATION_ERROR", "cursor does not match query parameters")
        except Exception:
            _log("get_order_list", "VALIDATION_ERROR", "cursor decode failed")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []

    # Filter
    def _match(o):
        if not isinstance(o, dict):
            return False
        if dt_from or dt_to:
            cdt = _dt_from_row(o.get("created_at"))
            if cdt is None:
                return False
            if dt_from and cdt < dt_from:
                return False
            if dt_to and cdt >= dt_to:
                return False
        if status is not None and o.get("status") != status:
            return False
        if exchange is not None and o.get("exchange") != exchange:
            return False
        if product is not None and o.get("product") != product:
            return False
        if side is not None and o.get("side") != side:
            return False
        if instrument_id is not None and o.get("instrument_id") != instrument_id:
            return False
        if trading_symbol is not None:
            if not isinstance(trading_symbol, str):
                return False
            if (o.get("trading_symbol") or "") != trading_symbol:
                return False
        if user_reference_id is not None:
            if not isinstance(user_reference_id, str):
                return False
            if (o.get("user_reference_id") or "") != user_reference_id:
                return False
        return True

    filtered = [o for o in orders if _match(o)]

    # Sort
    def _sort_key(o):
        dt = _dt_from_row(o.get(sort_by))
        # Put None last in desc, first in asc
        if dt is None:
            return (1, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
        return (0, dt)

    reverse = (sort_order == "desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)
    offset = cur["offset"] if cur else 0
    if offset > total:
        offset = total

    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {
            "offset": next_offset,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "from_ts": from_ts,
            "to_ts": to_ts,
            "status": status,
            "exchange": exchange,
            "product": product,
            "side": side,
            "instrument_id": instrument_id,
            "trading_symbol": trading_symbol,
            "user_reference_id": user_reference_id,
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "orders": page,
        "meta": {
            "total": total,
            "count": len(page),
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
    }
    _log("get_order_list", "OK")
    return resp

def get_order_details(order_id=None, groww_order_id=None, user_reference_id=None, **_extra):
    import json, os, datetime, time, hashlib, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}:{random.random()}".encode("utf-8")
        return f"{prefix}_01{hashlib.sha256(raw).hexdigest()[:24].upper()}"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "get_order_details",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if order_id is None and groww_order_id is None and user_reference_id is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Provide one of order_id, groww_order_id, or user_reference_id")

    if order_id is not None:
        if not isinstance(order_id, str) or not order_id.strip() or not order_id.startswith("grw_ord_"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid order_id format", field="order_id")
    if groww_order_id is not None and (not isinstance(groww_order_id, str) or not groww_order_id.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "groww_order_id must be a non-empty string", field="groww_order_id")
    if user_reference_id is not None and (not isinstance(user_reference_id, str) or not user_reference_id.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_reference_id must be a non-empty string", field="user_reference_id")

    orders = _load("orders.json")
    if not isinstance(orders, list):
        orders = []

    found = None
    if order_id is not None:
        for o in orders:
            if isinstance(o, dict) and o.get("id") == order_id:
                found = o
                break
    if found is None and groww_order_id is not None:
        for o in orders:
            if isinstance(o, dict) and o.get("groww_order_id") == groww_order_id:
                found = o
                break
    if found is None and user_reference_id is not None:
        for o in orders:
            if isinstance(o, dict) and o.get("user_reference_id") == user_reference_id:
                found = o
                break

    if found is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Order not found")

    _log("ok", meta={"order_id": found.get("id"), "groww_order_id": found.get("groww_order_id")})
    return {"order": found}

def get_order_trades(order_id, groww_order_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, hashlib, random, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}:{random.random()}".encode("utf-8")
        return f"{prefix}_01{hashlib.sha256(raw).hexdigest()[:24].upper()}"
    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "get_order_trades",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    try:
        if not isinstance(order_id, str) or not order_id.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order_id must be a non-empty string", field="order_id")
        if not re.match(r"^grw_ord_[0-9A-HJKMNP-TV-Z]{16,}$", order_id.strip()):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order_id does not match required format", field="order_id")

        if groww_order_id is not None and (not isinstance(groww_order_id, str) or not groww_order_id.strip()):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "groww_order_id must be a non-empty string when provided", field="groww_order_id")

        # limit: accept integers, or whole-number floats (audit passed floats)
        if limit is None:
            limit_i = 200
        else:
            if isinstance(limit, bool) or not isinstance(limit, (int, float)) or int(limit) != limit:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
            limit_i = int(limit)
        if limit_i < 1 or limit_i > 500:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 500", field="limit", minimum=1, maximum=500)

        if sort_by is None:
            sort_by = "trade_time"
        if sort_by not in ("trade_time", "created_at"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort_by must be one of: trade_time, created_at", field="sort_by")

        if sort_order is None:
            sort_order = "desc"
        if sort_order not in ("asc", "desc"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc", field="sort_order")

        # cursor: vendor schema says string. Accept whole-number floats by coercing to string token.
        cursor_obj = None
        if cursor is not None:
            if isinstance(cursor, (int, float)) and not isinstance(cursor, bool) and int(cursor) == cursor:
                cursor = str(int(cursor))
            if not isinstance(cursor, str) or not cursor.strip():
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
            cur = cursor.strip()
            if cur.isdigit():
                cursor_obj = {"offset": int(cur)}
            else:
                try:
                    raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
                    cursor_obj = json.loads(raw.decode("utf-8"))
                except Exception:
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "cursor is invalid/opaque token", field="cursor")
            if not isinstance(cursor_obj, dict) or "offset" not in cursor_obj:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid/opaque token", field="cursor")
            off = cursor_obj.get("offset")
            if isinstance(off, bool) or not isinstance(off, int) or off < 0:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid/opaque token", field="cursor")

        orders = _load("orders.json")
        if not isinstance(orders, list):
            orders = []
        order_row = None
        for r in orders:
            if isinstance(r, dict) and r.get("id") == order_id:
                order_row = r
                break
        if order_row is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Order not found", order_id=order_id)

        if groww_order_id is not None:
            if (order_row.get("groww_order_id") or "") != groww_order_id.strip():
                _log("error", "CONFLICT")
                return _err("CONFLICT", "groww_order_id does not match the resolved order", order_id=order_id, groww_order_id=groww_order_id)

        trades = _load("trades.json")
        if not isinstance(trades, list):
            trades = []

        rows = [t for t in trades if isinstance(t, dict) and t.get("order_id") == order_id]

        # Filter out invalid fills (business rule says fills must satisfy >0); keep but don't error on historic bad data
        def _valid_fill(t):
            fq = t.get("fill_quantity")
            fp = t.get("fill_price")
            return isinstance(fq, int) and fq > 0 and isinstance(fp, (int, float)) and (not isinstance(fp, bool)) and fp > 0

        rows = [t for t in rows if _valid_fill(t)]

        # Sort
        reverse = (sort_order == "desc")
        def _parse_sort_dt(v):
            if not isinstance(v, str) or not v:
                return None
            ss = v.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None

        def _key(t):
            dt = _parse_sort_dt(t.get(sort_by))
            # None values sort last consistently
            return (dt is None, dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), t.get("id") or "")
        rows.sort(key=_key, reverse=reverse)

        offset = 0
        if cursor_obj is not None:
            offset = int(cursor_obj.get("offset", 0))
            if offset > len(rows):
                offset = len(rows)

        page = rows[offset: offset + limit_i]
        next_offset = offset + len(page)
        has_more = next_offset < len(rows)
        next_cursor = None
        if has_more:
            payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

        out = {
            "order": {
                "id": order_row.get("id"),
                "groww_order_id": order_row.get("groww_order_id"),
                "user_reference_id": order_row.get("user_reference_id"),
                "status": order_row.get("status"),
            },
            "trades": page,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "limit": limit_i,
            "cursor": cursor if cursor is not None else None,
            "total": len(rows),
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
        _log("success", None, {"order_id": order_id, "returned": len(page), "total": len(rows), "has_more": has_more})
        return out
    except Exception as e:
        _log("error", "FAILED", {"exception": str(e)})
        return _err("FAILED", "Internal error")

def get_holdings(as_of=None, refresh=None, ttl_seconds=None, **_extra):
    import json, os, datetime, time, random

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string")
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time")

    def _dt_from_row(v):
        if not v:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            try:
                ss = v[:-1] + "+00:00" if v.endswith("Z") else v
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    def _log(endpoint, status_code, detail=None):
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "status": status_code,
            "detail": detail,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso(),
        }
        fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save(fname, logs)

    # Validate inputs
    dt_as_of, e = _parse_dt(as_of, "as_of")
    if e:
        _log("get_holdings", "VALIDATION_ERROR", "bad as_of")
        return e
    if refresh is not None and not isinstance(refresh, bool):
        _log("get_holdings", "VALIDATION_ERROR", "bad refresh")
        return _err("VALIDATION_ERROR", "refresh must be a boolean", field="refresh")
    if ttl_seconds is None:
        ttl_seconds = 60
    if not isinstance(ttl_seconds, int) or ttl_seconds < 0:
        _log("get_holdings", "VALIDATION_ERROR", "bad ttl_seconds")
        return _err("VALIDATION_ERROR", "ttl_seconds must be an integer >= 0", field="ttl_seconds")

    snapshots = _load("portfolio_snapshots.json")
    if not isinstance(snapshots, list):
        snapshots = []

    now = _now()

    # Helper: determine freshness
    def _is_fresh(snap):
        if not isinstance(snap, dict):
            return False
        if snap.get("snapshot_type") != "holdings":
            return False
        if snap.get("status") != "fresh":
            return False
        asof = _dt_from_row(snap.get("as_of"))
        if asof is None:
            return False
        ttl = snap.get("ttl_seconds")
        if not isinstance(ttl, int) or ttl < 0:
            return False
        return (now - asof).total_seconds() <= ttl

    # Choose latest fresh snapshot (optionally <= as_of)
    def _eligible(snap):
        if not _is_fresh(snap):
            return False
        if dt_as_of is not None:
            asof = _dt_from_row(snap.get("as_of"))
            if asof is None or asof > dt_as_of:
                return False
        return True

    latest = None
    for s in snapshots:
        if not _eligible(s):
            continue
        if latest is None:
            latest = s
            continue
        da = _dt_from_row(latest.get("as_of"))
        db = _dt_from_row(s.get("as_of"))
        if da is None or (db is not None and db > da):
            latest = s

    if refresh is not True and latest is not None:
        _log("get_holdings", "OK")
        return {"snapshot": latest, "source": "cache"}

    # "Fetch upstream" (offline): create a new snapshot; if instruments exist, synthesize minimal stable-looking holdings.
    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []

    # Use a deterministic-ish sample from active instruments
    active = [i for i in instruments if isinstance(i, dict) and i.get("status") == "active"]
    sample = active[: min(25, len(active))]

    holdings = []
    for ins in sample:
        tsym = ins.get("trading_symbol")
        exch = ins.get("exchange")
        if not tsym or not exch:
            continue
        qty = 1 + (abs(hash((tsym, exch))) % 50)
        avg = round(10 + (abs(hash(("avg", tsym))) % 5000) / 10.0, 2)
        holdings.append({
            "instrument_id": ins.get("id"),
            "trading_symbol": tsym,
            "exchange": exch,
            "quantity": qty,
            "average_price": avg,
            "isin": ins.get("isin"),
            "name": ins.get("name"),
        })

    # If nothing to return, still a valid (fresh) snapshot.
    new_as_of = dt_as_of if dt_as_of is not None else now
    new_id = f"grw_ps_{int(time.time()*1000)}_{os.getpid()}"
    created = _now_iso()
    # Simulate rare upstream failures (kept deterministic by time slice) but avoid raising.
    fail = False
    # Small probability based on current second
    if int(time.time()) % 97 == 0:
        fail = True

    if fail:
        snap = {
            "id": new_id,
            "as_of": new_as_of.isoformat(),
            "snapshot_type": "holdings",
            "status": "failed",
            "ttl_seconds": ttl_seconds,
            "data": {"holdings": []},
            "error_message": "Upstream holdings fetch failed",
            "created_at": created,
            "updated_at": created,
        }
        snapshots.append(snap)
        _save("portfolio_snapshots.json", snapshots)
        _log("get_holdings", "OK", "upstream_failed")
        return {"snapshot": snap, "source": "upstream"}
    else:
        snap = {
            "id": new_id,
            "as_of": new_as_of.isoformat(),
            "snapshot_type": "holdings",
            "status": "fresh",
            "ttl_seconds": ttl_seconds,
            "data": {"holdings": holdings},
            "error_message": None,
            "created_at": created,
            "updated_at": created,
        }
        # Enforce unique(snapshot_type, as_of): if exists, replace (idempotent by as_of) else append
        replaced = False
        for idx, s in enumerate(snapshots):
            if isinstance(s, dict) and s.get("snapshot_type") == "holdings" and s.get("as_of") == snap["as_of"]:
                snapshots[idx] = snap
                replaced = True
                break
        if not replaced:
            snapshots.append(snap)
        _save("portfolio_snapshots.json", snapshots)
        _log("get_holdings", "OK")
        return {"snapshot": snap, "source": "upstream"}

def get_positions(as_of=None, refresh=None, ttl_seconds=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)
    now = t0

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string")
        try:
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is not a valid datetime")

    def _log(status, latency_ms, error_code=None):
        # Schema provided does not include an audit/request-log collection.
        return

    # Validate inputs
    if refresh is not None and not isinstance(refresh, bool):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "refresh must be a boolean")

    if ttl_seconds is not None:
        if not isinstance(ttl_seconds, int):
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "ttl_seconds must be an integer")
        if ttl_seconds < 0:
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "ttl_seconds must be >= 0")

    as_of_dt, e = _parse_dt(as_of, "as_of")
    if e:
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("error", latency, "VALIDATION_ERROR")
        return e

    snapshots = _load("portfolio_snapshots.json")

    def _dt_from_row(row):
        v = row.get("as_of")
        if isinstance(v, str):
            try:
                vv = v
                if vv.endswith("Z"):
                    vv = vv[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(vv)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except ValueError:
                return None
        return None

    def _is_fresh(row):
        if row.get("status") != "fresh":
            return False
        asof = _dt_from_row(row)
        if asof is None:
            return False
        ttl = row.get("ttl_seconds")
        if not isinstance(ttl, int) or ttl < 0:
            return False
        return (now - asof).total_seconds() <= ttl

    def _select_cached():
        relevant = [r for r in snapshots if r.get("snapshot_type") == "positions"]
        if as_of_dt is not None:
            # nearest snapshot at or before as_of
            cand = []
            for r in relevant:
                dt = _dt_from_row(r)
                if dt is not None and dt <= as_of_dt:
                    cand.append((dt, r))
            cand.sort(key=lambda x: x[0], reverse=True)
            for _, r in cand:
                if _is_fresh(r):
                    return r
            return None
        # latest fresh
        cand = []
        for r in relevant:
            dt = _dt_from_row(r)
            if dt is not None:
                cand.append((dt, r))
        cand.sort(key=lambda x: x[0], reverse=True)
        for _, r in cand:
            if _is_fresh(r):
                return r
        return None

    def _new_id(prefix="grw_ps_"):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def base32(nbytes=12):
            b = secrets.token_bytes(nbytes)
            out = []
            acc = 0
            bits = 0
            for by in b:
                acc = (acc << 8) | by
                bits += 8
                while bits >= 5:
                    out.append(alphabet[(acc >> (bits - 5)) & 31])
                    bits -= 5
            if bits:
                out.append(alphabet[(acc << (5 - bits)) & 31])
            return "".join(out)
        existing = {r.get("id") for r in snapshots if isinstance(r, dict)}
        for _ in range(50):
            nid = prefix + base32(12)
            if nid not in existing:
                return nid
        return prefix + base32(16)

    def _fetch_upstream_positions():
        # Offline "upstream" strategy: reuse latest stored positions payload regardless of status if available;
        # otherwise create an empty positions snapshot as fresh.
        relevant = [r for r in snapshots if r.get("snapshot_type") == "positions"]
        best = None
        best_dt = None
        for r in relevant:
            dt = _dt_from_row(r)
            if dt is None:
                continue
            if best_dt is None or dt > best_dt:
                best = r
                best_dt = dt

        payload = {"positions": []}
        if isinstance(best, dict) and isinstance(best.get("data"), dict):
            d = best.get("data")
            if isinstance(d.get("positions"), list):
                payload = {"positions": d.get("positions")}

        new_row = {
            "id": _new_id(),
            "as_of": _iso(now),
            "snapshot_type": "positions",
            "status": "fresh",
            "ttl_seconds": int(ttl_seconds) if ttl_seconds is not None else (best.get("ttl_seconds") if isinstance(best, dict) and isinstance(best.get("ttl_seconds"), int) and best.get("ttl_seconds") >= 0 else 0),
            "data": payload,
            "error_message": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        snapshots.append(new_row)
        _save("portfolio_snapshots.json", snapshots)
        return new_row

    use_refresh = bool(refresh) if refresh is not None else False
    row = None if use_refresh else _select_cached()
    if row is None:
        # Fetch upstream and persist
        row = _fetch_upstream_positions()

    # Return single snapshot list (not paged)
    data = row.get("data")
    positions = []
    if isinstance(data, dict) and isinstance(data.get("positions"), list):
        positions = data.get("positions")

    latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
    _log("ok", latency)
    return {
        "snapshot": {
            "id": row.get("id"),
            "as_of": row.get("as_of"),
            "snapshot_type": row.get("snapshot_type"),
            "status": row.get("status"),
            "ttl_seconds": row.get("ttl_seconds"),
        },
        "positions": positions,
    }

def get_position_by_symbol(trading_symbol, exchange=None, as_of=None, refresh=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)
    now = t0

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string")
        try:
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is not a valid datetime")

    def _log(status, latency_ms, error_code=None):
        return

    # Validate
    if not isinstance(trading_symbol, str) or not trading_symbol.strip():
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "trading_symbol must be a non-empty string")
    trading_symbol_q = trading_symbol.strip()

    allowed_ex = ["NSE", "BSE", "NFO", "CDS", "MCX", "BFO", "UNKNOWN"]
    if exchange is not None:
        if not isinstance(exchange, str):
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "exchange must be a string")
        if exchange not in allowed_ex:
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "exchange must be one of NSE, BSE, NFO, CDS, MCX, BFO, UNKNOWN")

    if refresh is not None and not isinstance(refresh, bool):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "refresh must be a boolean")

    as_of_dt, e = _parse_dt(as_of, "as_of")
    if e:
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("error", latency, "VALIDATION_ERROR")
        return e

    # Ensure instrument exists for trading_symbol (and exchange if provided)
    instruments = _load("instruments.json")
    matches = []
    for ins in instruments:
        if not isinstance(ins, dict):
            continue
        if (ins.get("trading_symbol") or "") == trading_symbol_q:
            if exchange is None or ins.get("exchange") == exchange:
                matches.append(ins)

    if exchange is None:
        # if multiple exchanges match, require explicit disambiguation (especially UNKNOWN)
        ex_set = {m.get("exchange") for m in matches if isinstance(m.get("exchange"), str)}
        if len(ex_set) > 1:
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("error", latency, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "trading_symbol is ambiguous across exchanges; provide exchange to disambiguate", exchanges=sorted(ex_set))
    if not matches:
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("error", latency, "NOT_FOUND")
        return _err("NOT_FOUND", "Instrument not found for given trading_symbol/exchange")

    # Load positions snapshot (reuse get_positions logic inline)
    snapshots = _load("portfolio_snapshots.json")

    def _dt_from_row(row):
        v = row.get("as_of")
        if isinstance(v, str):
            try:
                vv = v
                if vv.endswith("Z"):
                    vv = vv[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(vv)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except ValueError:
                return None
        return None

    def _is_fresh(row):
        if row.get("status") != "fresh":
            return False
        asof = _dt_from_row(row)
        if asof is None:
            return False
        ttl = row.get("ttl_seconds")
        if not isinstance(ttl, int) or ttl < 0:
            return False
        return (now - asof).total_seconds() <= ttl

    def _new_id(prefix="grw_ps_"):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def base32(nbytes=12):
            b = secrets.token_bytes(nbytes)
            out = []
            acc = 0
            bits = 0
            for by in b:
                acc = (acc << 8) | by
                bits += 8
                while bits >= 5:
                    out.append(alphabet[(acc >> (bits - 5)) & 31])
                    bits -= 5
            if bits:
                out.append(alphabet[(acc << (5 - bits)) & 31])
            return "".join(out)
        existing = {r.get("id") for r in snapshots if isinstance(r, dict)}
        for _ in range(50):
            nid = prefix + base32(12)
            if nid not in existing:
                return nid
        return prefix + base32(16)

    def _select_cached():
        relevant = [r for r in snapshots if r.get("snapshot_type") == "positions"]
        if as_of_dt is not None:
            cand = []
            for r in relevant:
                dt = _dt_from_row(r)
                if dt is not None and dt <= as_of_dt:
                    cand.append((dt, r))
            cand.sort(key=lambda x: x[0], reverse=True)
            for _, r in cand:
                if _is_fresh(r):
                    return r
            return None
        cand = []
        for r in relevant:
            dt = _dt_from_row(r)
            if dt is not None:
                cand.append((dt, r))
        cand.sort(key=lambda x: x[0], reverse=True)
        for _, r in cand:
            if _is_fresh(r):
                return r
        return None

    def _fetch_upstream_positions():
        relevant = [r for r in snapshots if r.get("snapshot_type") == "positions"]
        best = None
        best_dt = None
        for r in relevant:
            dt = _dt_from_row(r)
            if dt is None:
                continue
            if best_dt is None or dt > best_dt:
                best = r
                best_dt = dt

        payload = {"positions": []}
        if isinstance(best, dict) and isinstance(best.get("data"), dict):
            d = best.get("data")
            if isinstance(d.get("positions"), list):
                payload = {"positions": d.get("positions")}

        new_row = {
            "id": _new_id(),
            "as_of": _iso(now),
            "snapshot_type": "positions",
            "status": "fresh",
            "ttl_seconds": int(best.get("ttl_seconds")) if isinstance(best, dict) and isinstance(best.get("ttl_seconds"), int) and best.get("ttl_seconds") >= 0 else 0,
            "data": payload,
            "error_message": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        snapshots.append(new_row)
        _save("portfolio_snapshots.json", snapshots)
        return new_row

    row = None if bool(refresh) else _select_cached()
    if row is None:
        row = _fetch_upstream_positions()

    positions = []
    if isinstance(row.get("data"), dict) and isinstance(row["data"].get("positions"), list):
        positions = row["data"]["positions"]

    # Filter position by symbol (and exchange if possible)
    def _pos_match(p):
        if not isinstance(p, dict):
            return False
        sym = p.get("trading_symbol") or p.get("symbol") or p.get("tradingsymbol")
        if not isinstance(sym, str):
            return False
        if sym != trading_symbol_q:
            return False
        if exchange is None:
            return True
        ex = p.get("exchange")
        if isinstance(ex, str) and ex == exchange:
            return True
        # Some payloads may not carry exchange; accept match if absent.
        if ex is None:
            return True
        return False

    matched = [p for p in positions if _pos_match(p)]
    if not matched:
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("error", latency, "NOT_FOUND")
        return _err("NOT_FOUND", "No matching position for the given trading_symbol/exchange")

    # If multiple matches, return the first but also include count for observability
    result = matched[0]

    latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
    _log("ok", latency)
    return {
        "snapshot": {
            "id": row.get("id"),
            "as_of": row.get("as_of"),
            "snapshot_type": row.get("snapshot_type"),
            "status": row.get("status"),
            "ttl_seconds": row.get("ttl_seconds"),
        },
        "position": result,
        "match_count": len(matched),
    }

