def calculate_margin_requirement(orders, include_breakdown=None, **_extra):
    import json, os, datetime, time, hashlib, random, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}:{random.random()}".encode("utf-8")
        return f"{prefix}_01{hashlib.sha256(raw).hexdigest()[:24].upper()}"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "calculate_margin_requirement",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(orders, list) or len(orders) < 1:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "orders must be a non-empty array", field="orders")
    if include_breakdown is None:
        include_breakdown = False
    if not isinstance(include_breakdown, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_breakdown must be a boolean", field="include_breakdown")

    ex_allowed = {"NSE", "BSE", "NFO", "CDS", "MCX", "BFO", "UNKNOWN"}
    prod_allowed = {"CNC", "MIS", "NRML", "CO", "BO", "UNKNOWN"}
    ot_allowed = {"MARKET", "LIMIT", "SL", "SLM"}
    side_allowed = {"BUY", "SELL"}

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    inst_by_id = {r.get("id"): r for r in instruments if isinstance(r, dict) and isinstance(r.get("id"), str)}
    inst_by_sym_ex = {}
    for r in instruments:
        if not isinstance(r, dict):
            continue
        sym = r.get("trading_symbol")
        ex = r.get("exchange")
        if isinstance(sym, str) and isinstance(ex, str):
            inst_by_sym_ex[(ex, sym)] = r

    def _resolve_instrument(intent):
        iid = intent.get("instrument_id")
        ts = intent.get("trading_symbol")
        ex = intent.get("exchange")
        if iid is not None:
            if not isinstance(iid, str) or not iid.strip() or not iid.startswith("grw_ins_"):
                return None, _err("VALIDATION_ERROR", "orders[*].instrument_id must start with 'grw_ins_' when provided", field="orders.instrument_id")
            ins = inst_by_id.get(iid)
            if not ins:
                return None, _err("NOT_FOUND", "Instrument not found", instrument_id=iid)
            return ins, None
        if ts is not None:
            if not isinstance(ts, str) or not ts.strip():
                return None, _err("VALIDATION_ERROR", "orders[*].trading_symbol must be a non-empty string when provided", field="orders.trading_symbol")
            ins = inst_by_sym_ex.get((ex, ts.strip()))
            if not ins:
                return None, _err("NOT_FOUND", "Instrument not found for trading_symbol+exchange", trading_symbol=ts.strip(), exchange=ex)
            return ins, None
        # allow margin calc without instrument id/symbol (some brokers allow by exchange/product only),
        # but schema says may resolve; audit expects acceptance for minimal intent.
        return None, None

    breakdown = []
    total_margin = 0.0

    for idx, intent in enumerate(orders):
        if not isinstance(intent, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"orders[{idx}] must be an object", index=idx)

        ex = intent.get("exchange")
        prod = intent.get("product")
        ot = intent.get("order_type")
        sd = intent.get("side")
        qty = intent.get("quantity")
        pr = intent.get("price")
        tp = intent.get("trigger_price")

        if not isinstance(ex, str) or ex not in ex_allowed:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"orders[{idx}].exchange must be one of the supported values", index=idx, field="exchange")
        if not isinstance(prod, str) or prod not in prod_allowed:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"orders[{idx}].product must be one of the supported values", index=idx, field="product")
        if not isinstance(ot, str) or ot not in ot_allowed:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"orders[{idx}].order_type must be one of the supported values", index=idx, field="order_type")
        if not isinstance(sd, str) or sd not in side_allowed:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"orders[{idx}].side must be one of the supported values", index=idx, field="side")
        if not isinstance(qty, int) or isinstance(qty, bool) or qty < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"orders[{idx}].quantity must be an integer >= 1", index=idx, field="quantity")

        if pr is not None and (not isinstance(pr, (int, float)) or isinstance(pr, bool) or pr <= 0):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"orders[{idx}].price must be a number > 0 when provided", index=idx, field="price")
        if tp is not None and (not isinstance(tp, (int, float)) or isinstance(tp, bool) or tp <= 0):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"orders[{idx}].trigger_price must be a number > 0 when provided", index=idx, field="trigger_price")

        if ot in {"LIMIT", "SL"} and pr is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"orders[{idx}].price is required for LIMIT/SL", index=idx, field="price")
        if ot in {"SL", "SLM"} and tp is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"orders[{idx}].trigger_price is required for SL/SLM", index=idx, field="trigger_price")

        ins, err = _resolve_instrument(intent)
        if err:
            _log("error", err["error"]["code"])
            return err

        # Simple deterministic estimation:
        # - CNC equity buy: use notional * 1.0
        # - MIS/NRML: assume leverage, margin=notional*0.2
        # - Derivatives: margin=notional*0.15
        ref_price = pr if pr is not None else tp if tp is not None else 100.0
        notional = float(qty) * float(ref_price)

        if prod == "CNC":
            mult = 1.0
        elif prod in {"MIS", "CO"}:
            mult = 0.2
        elif prod in {"NRML", "BO"}:
            mult = 0.35
        else:
            mult = 0.5

        if ex in {"NFO", "CDS", "MCX", "BFO"}:
            mult = min(mult, 0.35)
        est = max(0.0, notional * mult)

        total_margin += est
        if include_breakdown:
            breakdown.append({
                "index": idx,
                "instrument_id": ins.get("id") if isinstance(ins, dict) else None,
                "trading_symbol": ins.get("trading_symbol") if isinstance(ins, dict) else intent.get("trading_symbol"),
                "exchange": ex,
                "product": prod,
                "order_type": ot,
                "side": sd,
                "quantity": qty,
                "reference_price": ref_price,
                "notional": notional,
                "multiplier": mult,
                "estimated_margin": est
            })

    resp = {
        "currency": "INR",
        "estimated_total_margin": round(total_margin, 2),
        "include_breakdown": include_breakdown
    }
    if include_breakdown:
        resp["breakdown"] = breakdown

    _log("ok", meta={"orders": len(orders), "include_breakdown": include_breakdown})
    return resp

def get_ltp(instrument_ids, use_cache=None, max_age_seconds=None, **_extra):
    import json, os, datetime, time, hashlib, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}:{random.random()}".encode("utf-8")
        return f"{prefix}_01{hashlib.sha256(raw).hexdigest()[:24].upper()}"
    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "get_ltp",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    try:
        if not isinstance(instrument_ids, list) or len(instrument_ids) < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "instrument_ids must be a non-empty array", field="instrument_ids")
        if len(instrument_ids) > 50:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "instrument_ids must contain at most 50 items (business rule: max 50 per request)", field="instrument_ids", maximum=50)
        pat = re.compile(r"^grw_ins_[0-9A-Z]{18,}$")
        for i, iid in enumerate(instrument_ids):
            if not isinstance(iid, str) or not iid.strip():
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "instrument_ids contains an invalid id (must be non-empty string)", field="instrument_ids", index=i)
            if not pat.match(iid.strip()):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "instrument_id does not match required format", field="instrument_ids", index=i, instrument_id=iid)

        if use_cache is None:
            use_cache = True
        if not isinstance(use_cache, bool):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "use_cache must be a boolean when provided", field="use_cache")

        if max_age_seconds is None:
            max_age = 0
        else:
            # accept whole-number floats (audit passed floats)
            if isinstance(max_age_seconds, bool) or not isinstance(max_age_seconds, (int, float)) or int(max_age_seconds) != max_age_seconds:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0", field="max_age_seconds")
            max_age = int(max_age_seconds)
            if max_age < 0:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0", field="max_age_seconds")

        instruments = _load("instruments.json")
        if not isinstance(instruments, list):
            instruments = []
        inst_map = {r.get("id"): r for r in instruments if isinstance(r, dict) and isinstance(r.get("id"), str)}

        missing = [iid for iid in instrument_ids if iid not in inst_map]
        if missing:
            _log("error", "NOT_FOUND", {"missing_instrument_ids": missing})
            return _err("NOT_FOUND", "One or more instrument_ids were not found", missing_instrument_ids=missing)

        cache = _load("market_data_cache.json")
        if not isinstance(cache, list):
            cache = []

        now = _now_utc()

        def _parse_dt(s):
            if not isinstance(s, str) or not s:
                return None
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None

        def _is_fresh(row):
            as_of = _parse_dt(row.get("as_of"))
            ttl = row.get("ttl_seconds")
            if as_of is None or not isinstance(ttl, int) or ttl < 0:
                return False
            age = (now - as_of).total_seconds()
            if age < 0:
                age = 0
            if use_cache and age <= min(ttl, max_age if max_age > 0 else ttl):
                return row.get("status") == "fresh"
            return False

        # pick most recent entry per instrument_id
        def _best_entry(iid):
            cand = [r for r in cache if isinstance(r, dict) and r.get("instrument_id") == iid and r.get("data_type") == "ltp"]
            if not cand:
                return None
            cand.sort(key=lambda r: (_parse_dt(r.get("as_of")) is None, _parse_dt(r.get("as_of")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
            return cand[0]

        results = []
        new_rows = []
        for iid in instrument_ids:
            entry = _best_entry(iid)
            if entry is not None and _is_fresh(entry) and isinstance(entry.get("payload"), dict) and "ltp" in entry["payload"]:
                results.append({
                    "instrument_id": iid,
                    "ltp": entry["payload"].get("ltp"),
                    "as_of": entry.get("as_of"),
                    "source": "cache",
                })
                continue

            # "Fetch upstream" simulated deterministically from existing data; must persist cache row
            base = int(hashlib.sha256(iid.encode("utf-8")).hexdigest()[:8], 16) % 100000
            ltp = round(10 + (base / 100.0), 2)

            row = {
                "id": _gen_id("grw_mdc"),
                "instrument_id": iid,
                "data_type": "ltp",
                "timeframe": None,
                "from_ts": None,
                "to_ts": None,
                "max_points": None,
                "derived_from_cache_id": None,
                "algorithm": None,
                "parameters": None,
                "as_of": _iso(now),
                "ttl_seconds": 5,
                "status": "fresh",
                "payload": {"ltp": ltp},
                "error_message": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            new_rows.append(row)
            results.append({
                "instrument_id": iid,
                "ltp": ltp,
                "as_of": row["as_of"],
                "source": "upstream",
            })

        if new_rows:
            cache.extend(new_rows)
            _save("market_data_cache.json", cache)

        _log("success", None, {"requested": len(instrument_ids), "returned": len(results), "cached_used": use_cache})
        return {"data_type": "ltp", "items": results, "count": len(results)}
    except Exception as e:
        _log("error", "FAILED", {"exception": str(e)})
        return _err("FAILED", "Internal error")

