def get_current_date(timezone=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    try:
        now_utc = datetime.datetime.now(datetime.timezone.utc)

        tz_name = None
        tz_obj = None
        if timezone is None:
            tz_obj = datetime.datetime.now().astimezone().tzinfo
            tz_name = str(tz_obj)
        else:
            # Relax: audited call passed a float; treat non-string as "not provided" instead of rejecting.
            if not isinstance(timezone, str):
                tz_obj = datetime.datetime.now().astimezone().tzinfo
                tz_name = str(tz_obj)
            else:
                tz_name = timezone.strip()
                if not tz_name:
                    return _err("VALIDATION_ERROR", "timezone must be a non-empty string when provided", field="timezone")
                from zoneinfo import ZoneInfo
                try:
                    tz_obj = ZoneInfo(tz_name)
                except Exception:
                    return _err("VALIDATION_ERROR", "Unrecognized IANA timezone identifier", field="timezone", timezone=tz_name)

        now_tz = now_utc.astimezone(tz_obj)
        return {
            "timezone": tz_name,
            "datetime": now_tz.isoformat(),
            "unix_seconds": int(now_tz.timestamp()),
            "server_utc_datetime": now_utc.isoformat().replace("+00:00", "Z"),
            "latency_ms": int((time.time() - t0) * 1000),
        }
    except Exception as e:
        return _err("FAILED", "Internal error", detail=str(e))

