        return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0", field="max_age_seconds")

    fdt, e = _parse_dt(from_ts, "from_ts")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    tdt, e = _parse_dt(to_ts, "to_ts")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e

    if fdt is None:
        # default to a small window ending now
        tdt = tdt or _now_utc()
        fdt = tdt - datetime.timedelta(days=1)
    if tdt is None:
        tdt = _now_utc()

    if fdt > tdt:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from_ts must be <= to_ts", field="from_ts")

    # Timeframe range constraints (business rules)
    limits_days = {
        "1min": 3,
        "5min": 15,
        "10min": 30,
        "1hr": 150,
        "4hr": 365,
        "daily": 1080,
        "weekly": None
    }
    max_days = limits_days[timeframe]
    if max_days is not None:
        delta_days = (tdt - fdt).total_seconds() / 86400.0
        if delta_days > max_days + 1e-9:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Requested range exceeds maximum for timeframe {timeframe}", timeframe=timeframe, max_days=max_days)

    # Validate instrument existence
    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    if not any(isinstance(r, dict) and r.get("id") == instrument_id for r in instruments):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Instrument not found", instrument_id=instrument_id)

    cache = _load("market_data_cache.json")
    if not isinstance(cache, list):
        cache = []

    now = _now_utc()

    def _parse_row_dt(x):
        if not isinstance(x, str) or not x.strip():
            return None
        try:
            ss = x.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _row_matches(row):
        if not isinstance(row, dict):
            return False
        if row.get("instrument_id") != instrument_id:
            return False
        if row.get("data_type") != "historical_candles":
            return False
        if row.get("timeframe") != timeframe:
            return False
        rf = _parse_row_dt(row.get("from_ts"))
        rt = _parse_row_dt(row.get("to_ts"))
        if rf != fdt or rt != tdt:
            return False
        return True

    def _is_fresh(row):
        if row.get("status") != "fresh":
            return False
        as_of = _parse_row_dt(row.get("as_of"))
        ttl = row.get("ttl_seconds")
        if as_of is None or not isinstance(ttl, int) or ttl < 0:
            return False
        age = (now - as_of).total_seconds()
        if age > ttl:
            return False
        if age > max_age_seconds:
            return False
        return True

    best = None
    for row in cache:
        if not _row_matches(row):
            continue
        if use_cache and _is_fresh(row) and isinstance(row.get("payload"), dict):
            best = row
            break

    if best is not None:
        candles = best["payload"].get("candles")
        if not isinstance(candles, list):
            candles = []
        _log("ok", meta={"cache_hit": True, "candles": len(candles)})
        return {
            "instrument_id": instrument_id,
            "timeframe": timeframe,
            "from_ts": _iso(fdt),
            "to_ts": _iso(tdt),
            "as_of": best.get("as_of"),
            "candles": candles[:max_points] if isinstance(max_points, int) else candles,
            "used_cache": True
        }

    # Generate candles deterministically
    step = {
        "1min": 60, "5min": 300, "10min": 600, "1hr": 3600, "4hr": 14400, "daily": 86400, "weekly": 604800
    }[timeframe]
    total_secs = max(0, int((tdt - fdt).total_seconds()))
    points = max(0, total_secs // step)
    if isinstance(max_points, int):
        points = min(points, max_points)
    points = min(points, 50000)

    seed = int(hashlib.sha256(f"{instrument_id}:{timeframe}".encode("utf-8")).hexdigest()[:8], 16)
    base = 100 + (seed % 5000) / 10.0

    candles = []
    for i in range(points):
        ts = fdt + datetime.timedelta(seconds=step * i)
        drift = math.sin((seed % 1000 + i) / 17.0) * 0.8
        close = base + drift + (i * 0.01)
        open_ = close - 0.2
        high = close + 0.5
        low = close - 0.6
        vol = int(1000 + (seed % 500) + i * 3)
        candles.append({
            "timestamp": _iso(ts),
            "open": round(open_, 2),
            "high": round(high, 2),
            "low": round(low, 2),
            "close": round(close, 2),
            "volume": vol
        })

    entry = {
        "id": _gen_id("grw_mdc"),
        "instrument_id": instrument_id,
        "data_type": "historical_candles",
        "timeframe": timeframe,
        "from_ts": _iso(fdt),
        "to_ts": _iso(tdt),
        "max_points": max_points if isinstance(max_points, int) else None,
        "derived_from_cache_id": None,
        "algorithm": None,
        "parameters": None,
        "as_of": _iso(now),
        "ttl_seconds": 3600,
        "status": "fresh",
        "payload": {"candles": candles},
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    cache.append(entry)
    _save("market_data_cache.json", cache)

    _log("ok", meta={"cache_hit": False, "candles": len(candles), "cache_id": entry["id"]})
    return {
        "instrument_id": instrument_id,
        "timeframe": timeframe,
        "from_ts": _iso(fdt),
        "to_ts": _iso(tdt),
        "as_of": entry["as_of"],
        "candles": candles,
        "used_cache": False,
        "cache_id": entry["id"]
    }

def calculate_moving_averages(instrument_id, timeframe, from_ts=None, to_ts=None, sma_period=None, ema_period=None, price_field=None, use_cache=None, max_age_seconds=None, **_extra):
    import json, os, datetime, time, hashlib, random, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time", field=field)
    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}:{random.random()}".encode("utf-8")
        return f"{prefix}_01{hashlib.sha256(raw).hexdigest()[:24].upper()}"
    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "calculate_moving_averages",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    try:
        # Validate ids/enums
        if not isinstance(instrument_id, str) or not instrument_id.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "instrument_id must be a non-empty string", field="instrument_id")
        if not re.match(r"^grw_ins_[0-9A-Z]{18,}$", instrument_id.strip()):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "instrument_id does not match required format", field="instrument_id")

        tf_allowed = ("1min", "5min", "10min", "1hr", "4hr", "daily", "weekly")
        if timeframe not in tf_allowed:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "timeframe must be one of: 1min, 5min, 10min, 1hr, 4hr, daily, weekly", field="timeframe")

        # Periods: accept whole-number floats by coercion (audit passed floats); enforce >=1
        def _coerce_pos_int(v, field):
            if v is None:
                return None, _err("VALIDATION_ERROR", f"{field} is required", field=field)
            if isinstance(v, bool) or not isinstance(v, (int, float)) or int(v) != v:
                return None, _err("VALIDATION_ERROR", f"{field} must be an integer >= 1 (schema: integer; relaxing to accept whole-number floats)", field=field)
            iv = int(v)
            if iv < 1:
                return None, _err("VALIDATION_ERROR", f"{field} must be >= 1", field=field, minimum=1)
            return iv, None

        sma_p, e1 = _coerce_pos_int(sma_period, "sma_period")
        if e1:
            _log("error", e1["error"]["code"])
            return e1
        ema_p, e2 = _coerce_pos_int(ema_period, "ema_period")
        if e2:
            _log("error", e2["error"]["code"])
            return e2

        if price_field is None:
            price_field = "close"
        if price_field not in ("close", "open", "high", "low"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "price_field must be one of: close, open, high, low", field="price_field")

        if use_cache is None:
            use_cache = True
        if not isinstance(use_cache, bool):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "use_cache must be a boolean when provided", field="use_cache")

        if max_age_seconds is None:
            max_age = 0
        else:
            if isinstance(max_age_seconds, bool) or not isinstance(max_age_seconds, (int, float)) or int(max_age_seconds) != max_age_seconds:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0", field="max_age_seconds")
            max_age = int(max_age_seconds)
            if max_age < 0:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0", field="max_age_seconds")

        fdt, err = _parse_dt(from_ts, "from_ts")
        if err:
            _log("error", "VALIDATION_ERROR")
            return err
        tdt, err = _parse_dt(to_ts, "to_ts")
        if err:
            _log("error", "VALIDATION_ERROR")
            return err
        if fdt and tdt and fdt > tdt:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "from_ts must be <= to_ts", field="from_ts")

        instruments = _load("instruments.json")
        if not isinstance(instruments, list):
            instruments = []
        if not any(isinstance(r, dict) and r.get("id") == instrument_id for r in instruments):
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Instrument not found", instrument_id=instrument_id)

        cache = _load("market_data_cache.json")
        if not isinstance(cache, list):
            cache = []

        now = _now_utc()

        def _parse_iso(s):
            if not isinstance(s, str) or not s:
                return None
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None

        # Find or create historical candles cache entry (input series)
        def _find_hist():
            rows = [r for r in cache if isinstance(r, dict)
                    and r.get("instrument_id") == instrument_id
                    and r.get("data_type") == "historical_candles"
                    and r.get("timeframe") == timeframe
                    and r.get("from_ts") == (from_ts if from_ts is not None else None)
                    and r.get("to_ts") == (to_ts if to_ts is not None else None)
                    and r.get("status") == "fresh"
                    and isinstance(r.get("payload"), dict)
                    and isinstance(r["payload"].get("candles"), list)]
            if not rows:
                return None
            rows.sort(key=lambda r: (_parse_iso(r.get("as_of")) is None, _parse_iso(r.get("as_of")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
            return rows[0]

        hist = _find_hist()
        if hist is None:
            # Generate deterministic candle series; persist as fresh cache
            step_seconds = {
                "1min": 60, "5min": 300, "10min": 600, "1hr": 3600, "4hr": 14400, "daily": 86400, "weekly": 604800
            }[timeframe]
            end = tdt or now
            start = fdt or (end - datetime.timedelta(seconds=step_seconds * 200))
            # keep bounded points
            max_points = 2000
            total_seconds = max(0, int((end - start).total_seconds()))
            n = min(max_points, (total_seconds // step_seconds) + 1)
            base = int(hashlib.sha256((instrument_id + ":" + timeframe).encode("utf-8")).hexdigest()[:8], 16) % 100000
            candles = []
            for k in range(n):
                ts = start + datetime.timedelta(seconds=step_seconds * k)
                px = 10 + (base / 100.0) + (k * 0.01)
                o = round(px * 0.995, 2)
                h = round(px * 1.01, 2)
                l = round(px * 0.99, 2)
                c = round(px, 2)
                candles.append({"t": _iso(ts), "open": o, "high": h, "low": l, "close": c})
            hist = {
                "id": _gen_id("grw_mdc"),
                "instrument_id": instrument_id,
                "data_type": "historical_candles",
                "timeframe": timeframe,
                "from_ts": from_ts if from_ts is not None else None,
                "to_ts": to_ts if to_ts is not None else None,
                "max_points": len(candles),
                "derived_from_cache_id": None,
                "algorithm": None,
                "parameters": None,
                "as_of": _iso(now),
                "ttl_seconds": 60,
                "status": "fresh",
                "payload": {"candles": candles},
                "error_message": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            cache.append(hist)
            _save("market_data_cache.json", cache)

        derived_id = hist.get("id")
        params = {
            "sma_period": sma_p,
            "ema_period": ema_p,
            "price_field": price_field,
            "timeframe": timeframe,
            "from_ts": from_ts if from_ts is not None else None,
            "to_ts": to_ts if to_ts is not None else None,
        }

        # Cached indicator result?
        def _same_params(r):
            return isinstance(r.get("parameters"), dict) and all(r["parameters"].get(k) == params.get(k) for k in params.keys())

        def _fresh_ok(r):
            as_of = _parse_iso(r.get("as_of"))
            ttl = r.get("ttl_seconds")
            if as_of is None or not isinstance(ttl, int) or ttl < 0:
                return False
            age = (now - as_of).total_seconds()
            if age < 0:
                age = 0
            if not use_cache:
                return False
            return r.get("status") == "fresh" and age <= min(ttl, max_age if max_age > 0 else ttl)

        existing = [r for r in cache if isinstance(r, dict)
                    and r.get("instrument_id") == instrument_id
                    and r.get("data_type") == "indicator_result"
                    and r.get("algorithm") == "moving_averages"
                    and r.get("derived_from_cache_id") == derived_id
                    and _same_params(r)
                    and isinstance(r.get("payload"), dict)]
        existing.sort(key=lambda r: (_parse_iso(r.get("as_of")) is None, _parse_iso(r.get("as_of")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
        if existing and _fresh_ok(existing[0]):
            out = {
                "instrument_id": instrument_id,
                "timeframe": timeframe,
                "from_ts": from_ts,
                "to_ts": to_ts,
                "price_field": price_field,
                "sma_period": sma_p,
                "ema_period": ema_p,
                "derived_from_cache_id": derived_id,
                "as_of": existing[0].get("as_of"),
                "source": "cache",
                "series": existing[0]["payload"].get("series", []),
            }
            _log("success", None, {"source": "cache", "points": len(out["series"])})
            return out

        candles = hist.get("payload", {}).get("candles", [])
        prices = []
        times = []
        for c in candles:
            if isinstance(c, dict) and isinstance(c.get("t"), str) and isinstance(c.get(price_field), (int, float)) and not isinstance(c.get(price_field), bool):
                times.append(c["t"])
                prices.append(float(c[price_field]))

        n = len(prices)
        if n == 0:
            _log("error", "FAILED")
            return _err("FAILED", "No candle data available to compute moving averages")

        # Compute SMA
        sma = [None] * n
        if sma_p <= n:
            run_sum = sum(prices[:sma_p])
            sma[sma_p - 1] = run_sum / sma_p
            for i in range(sma_p, n):
                run_sum += prices[i] - prices[i - sma_p]
                sma[i] = run_sum / sma_p

        # Compute EMA
        ema = [None] * n
        alpha = 2.0 / (ema_p + 1.0)
        if ema_p <= n:
            seed = sum(prices[:ema_p]) / ema_p
            ema[ema_p - 1] = seed
            prev = seed
            for i in range(ema_p, n):
                prev = (prices[i] - prev) * alpha + prev
                ema[i] = prev

        series = []
        for i in range(n):
            series.append({
                "t": times[i],
                "sma": None if sma[i] is None else round(float(sma[i]), 6),
                "ema": None if ema[i] is None else round(float(ema[i]), 6),
            })

        row = {
            "id": _gen_id("grw_mdc"),
            "instrument_id": instrument_id,
            "data_type": "indicator_result",
            "timeframe": timeframe,
            "from_ts": from_ts if from_ts is not None else None,
            "to_ts": to_ts if to_ts is not None else None,
            "max_points": len(series),
            "derived_from_cache_id": derived_id,
            "algorithm": "moving_averages",
            "parameters": params,
            "as_of": _iso(now),
            "ttl_seconds": 300,
            "status": "fresh",
            "payload": {"series": series},
            "error_message": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        cache.append(row)
        _save("market_data_cache.json", cache)

        out = {
            "instrument_id": instrument_id,
            "timeframe": timeframe,
            "from_ts": from_ts,
            "to_ts": to_ts,
            "price_field": price_field,
            "sma_period": sma_p,
            "ema_period": ema_p,
            "derived_from_cache_id": derived_id,
            "as_of": row["as_of"],
            "source": "computed",
            "series": series,
        }
        _log("success", None, {"source": "computed", "points": len(series)})
        return out
    except Exception as e:
        _log("error", "FAILED", {"exception": str(e)})
        return _err("FAILED", "Internal error")

def calculate_rsi(instrument_id, timeframe, from_ts=None, to_ts=None, period=None, price_field=None, use_cache=None, max_age_seconds=None, **_extra):
    import json, os, datetime, re, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    if not isinstance(instrument_id, str) or not re.match(r"^grw_ins_[0-9A-Z]{18,}$", instrument_id):
        return _err("VALIDATION_ERROR", "Invalid instrument_id.")
    allowed_tf = {"1min", "5min", "10min", "1hr", "4hr", "daily", "weekly"}
    if timeframe not in allowed_tf:
        return _err("VALIDATION_ERROR", "Invalid timeframe.")
    if not isinstance(period, int) or period < 1:
        return _err("VALIDATION_ERROR", "period must be an integer >= 1.")
    if price_field is not None and price_field not in {"close", "open", "high", "low"}:
        return _err("VALIDATION_ERROR", "Invalid price_field.")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.")
    if max_age_seconds is not None and (not isinstance(max_age_seconds, int) or max_age_seconds < 0):
        return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0.")
    if from_ts is not None and not isinstance(from_ts, str):
        return _err("VALIDATION_ERROR", "from_ts must be an ISO 8601 string.")
    if to_ts is not None and not isinstance(to_ts, str):
        return _err("VALIDATION_ERROR", "to_ts must be an ISO 8601 string.")
    if price_field is None:
        price_field = "close"
    if use_cache is None:
        use_cache = True
    if max_age_seconds is None:
        max_age_seconds = 0

    def _parse_dt(s):
        if s is None:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    fdt = _parse_dt(from_ts)
    tdt = _parse_dt(to_ts)
    if (from_ts is not None and fdt is None) or (to_ts is not None and tdt is None):
        return _err("VALIDATION_ERROR", "from_ts/to_ts must be valid ISO 8601 date-time strings.")
    if fdt is not None and tdt is not None and fdt > tdt:
        return _err("VALIDATION_ERROR", "from_ts must be <= to_ts.")

    instruments = _load("instruments.json")
    if not any(r.get("id") == instrument_id for r in instruments):
        return _err("NOT_FOUND", "Instrument not found.", instrument_id=instrument_id)

    # Default window if not provided
    if fdt is None or tdt is None:
        tf_seconds = {"1min": 60, "5min": 300, "10min": 600, "1hr": 3600, "4hr": 14400, "daily": 86400, "weekly": 604800}[timeframe]
        tdt = now
        fdt = now - datetime.timedelta(seconds=tf_seconds * 500)

    cache = _load("market_data_cache.json")

    def _is_fresh(row):
        as_of = _parse_dt(row.get("as_of"))
        ttl = row.get("ttl_seconds")
        if as_of is None or not isinstance(ttl, int) or ttl < 0:
            return False
        return row.get("status") == "fresh" and (now - as_of).total_seconds() <= ttl

    def _age_ok(row):
        as_of = _parse_dt(row.get("as_of"))
        if as_of is None:
            return False
        return (now - as_of).total_seconds() <= max_age_seconds

    # Find or create candles cache
    hist_matches = [r for r in cache if r.get("instrument_id") == instrument_id and r.get("data_type") == "historical_candles"
                    and r.get("timeframe") == timeframe and r.get("from_ts") == fdt.isoformat() and r.get("to_ts") == tdt.isoformat()
                    and r.get("max_points") is None]
    hist_matches.sort(key=lambda r: _parse_dt(r.get("as_of")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), reverse=True)

    candles_entry = None
    if use_cache:
        for r in hist_matches:
            if _is_fresh(r) and _age_ok(r):
                candles_entry = r
                break

    if candles_entry is None:
        # generate candles inline (same constraints as get_historical_data)
        days_limits = {"1min": 3, "5min": 15, "10min": 30, "1hr": 150, "4hr": 365, "daily": 1080, "weekly": None}
        max_days = days_limits[timeframe]
        delta_days = (tdt - fdt).total_seconds() / 86400.0
        if max_days is not None and delta_days > max_days + 1e-9:
            return _err("VALIDATION_ERROR", "Requested date range exceeds timeframe limits.", timeframe=timeframe, max_days=max_days)

        import random
        tf_seconds = {"1min": 60, "5min": 300, "10min": 600, "1hr": 3600, "4hr": 14400, "daily": 86400, "weekly": 604800}[timeframe]
        total_points = max(0, min(int((tdt - fdt).total_seconds() // tf_seconds), 50000))
        seed_material = f"{instrument_id}|{timeframe}|{fdt.isoformat()}|{tdt.isoformat()}|None".encode("utf-8")
        seed = int(hashlib.sha256(seed_material).hexdigest()[:16], 16)
        rng = random.Random(seed)
        base = 50.0 + (seed % 5000) / 100.0
        last_close = base
        candles = []
        for i in range(total_points):
            ts = fdt + datetime.timedelta(seconds=tf_seconds * i)
            drift = (rng.random() - 0.5) * (0.6 if timeframe in {"1min", "5min", "10min"} else 1.5)
            o = max(0.01, last_close + drift)
            h = o + abs(rng.random() * 0.8)
            l = max(0.01, o - abs(rng.random() * 0.8))
            c = max(0.01, l + (h - l) * rng.random())
            v = int(100 + rng.random() * 10000)
            candles.append({"ts": ts.isoformat(), "open": round(o, 4), "high": round(h, 4), "low": round(l, 4), "close": round(c, 4), "volume": v})
            last_close = c

        def _new_id(prefix):
            return f"{prefix}{hashlib.sha256((prefix+now_iso+str(rng.random())).encode('utf-8')).hexdigest()[:24]}"
        candles_entry = {
            "id": _new_id("grw_mdc_"),
            "instrument_id": instrument_id,
            "data_type": "historical_candles",
            "timeframe": timeframe,
            "from_ts": fdt.isoformat(),
            "to_ts": tdt.isoformat(),
            "max_points": None,
            "derived_from_cache_id": None,
            "algorithm": None,
            "parameters": None,
            "as_of": now_iso,
            "ttl_seconds": 3600,
            "status": "fresh",
            "payload": {"candles": candles},
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        cache = _load("market_data_cache.json")
        cache.append(candles_entry)
        _save("market_data_cache.json", cache)

    # Indicator cache lookup
    cache = _load("market_data_cache.json")
    params = {"period": period, "price_field": price_field, "from_ts": fdt.isoformat(), "to_ts": tdt.isoformat()}
    ind_matches = []
    for r in cache:
        if r.get("instrument_id") != instrument_id:
            continue
        if r.get("data_type") != "indicator_result":
            continue
        if r.get("timeframe") != timeframe:
            continue
        if r.get("algorithm") != "rsi":
            continue
        if r.get("from_ts") != fdt.isoformat() or r.get("to_ts") != tdt.isoformat():
            continue
        if r.get("derived_from_cache_id") != candles_entry.get("id"):
            continue
        if r.get("parameters") != params:
            continue
        ind_matches.append(r)

    ind_matches.sort(key=lambda r: _parse_dt(r.get("as_of")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), reverse=True)
    if use_cache and ind_matches:
        for r in ind_matches:
            if _is_fresh(r) and _age_ok(r):
                latency_ms = int((time.time() - t0) * 1000)
                return {
                    "instrument_id": instrument_id,
                    "timeframe": timeframe,
                    "from_ts": fdt.isoformat(),
                    "to_ts": tdt.isoformat(),
                    "algorithm": "rsi",
                    "parameters": r.get("parameters"),
                    "source": "cache",
                    "as_of": r.get("as_of"),
                    "ttl_seconds": r.get("ttl_seconds"),
                    "result": r.get("payload"),
                    "meta": {"latency_ms": latency_ms, "cache_id": r.get("id"), "derived_from_cache_id": r.get("derived_from_cache_id")}
                }

    candles = (candles_entry.get("payload") or {}).get("candles", [])
    times, prices = [], []
    for c in candles:
        if isinstance(c, dict) and "ts" in c and price_field in c and isinstance(c.get(price_field), (int, float)):
            times.append(c["ts"])
            prices.append(float(c[price_field]))

    n = len(prices)
    if n < period + 1:
        err_msg = "Insufficient candle data to compute RSI."
        def _new_id(prefix):
            return f"{prefix}{hashlib.sha256((prefix+now_iso+'rsi').encode('utf-8')).hexdigest()[:24]}"
        entry = {
            "id": _new_id("grw_mdc_"),
            "instrument_id": instrument_id,
            "data_type": "indicator_result",
            "timeframe": timeframe,
            "from_ts": fdt.isoformat(),
            "to_ts": tdt.isoformat(),
            "max_points": None,
            "derived_from_cache_id": candles_entry.get("id"),
            "algorithm": "rsi",
            "parameters": params,
            "as_of": now_iso,
            "ttl_seconds": 300,
            "status": "failed",
            "payload": None,
            "error_message": err_msg,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        cache = _load("market_data_cache.json")
        cache.append(entry)
        _save("market_data_cache.json", cache)
        return _err("VALIDATION_ERROR", err_msg)

    # Wilder's RSI
    rsi = [None] * n
    gains = []
    losses = []
    for i in range(1, n):
        change = prices[i] - prices[i - 1]
        gains.append(max(change, 0.0))
        losses.append(max(-change, 0.0))

    avg_gain = sum(gains[:period]) / period
    avg_loss = sum(losses[:period]) / period

    # RSI at index period
    def _calc_rsi(ag, al):
        if al == 0.0 and ag == 0.0:
            return 50.0
        if al == 0.0:
            return 100.0
        rs = ag / al
        return 100.0 - (100.0 / (1.0 + rs))

    rsi[period] = _calc_rsi(avg_gain, avg_loss)

    for i in range(period + 1, n):
        g = gains[i - 1]
        l = losses[i - 1]
        avg_gain = (avg_gain * (period - 1) + g) / period
        avg_loss = (avg_loss * (period - 1) + l) / period
        rsi[i] = _calc_rsi(avg_gain, avg_loss)

    series = [{"ts": times[i], "rsi": (None if rsi[i] is None else round(float(rsi[i]), 6))} for i in range(n)]
    payload = {"series": series, "price_field": price_field}

    def _new_id(prefix):
        return f"{prefix}{hashlib.sha256((prefix+now_iso+'rsi'+instrument_id).encode('utf-8')).hexdigest()[:24]}"
    entry = {
        "id": _new_id("grw_mdc_"),
        "instrument_id": instrument_id,
        "data_type": "indicator_result",
        "timeframe": timeframe,
        "from_ts": fdt.isoformat(),
        "to_ts": tdt.isoformat(),
        "max_points": None,
        "derived_from_cache_id": candles_entry.get("id"),
        "algorithm": "rsi",
        "parameters": params,
        "as_of": now_iso,
        "ttl_seconds": 3600,
        "status": "fresh",
        "payload": payload,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    cache = _load("market_data_cache.json")
    cache.append(entry)
    _save("market_data_cache.json", cache)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "instrument_id": instrument_id,
        "timeframe": timeframe,
        "from_ts": fdt.isoformat(),
        "to_ts": tdt.isoformat(),
        "algorithm": "rsi",
        "parameters": params,
        "source": "upstream",
        "as_of": entry["as_of"],
        "ttl_seconds": entry["ttl_seconds"],
        "result": payload,
        "meta": {"latency_ms": latency_ms, "cache_id": entry["id"], "derived_from_cache_id": entry["derived_from_cache_id"]}
    }

def calculate_bollinger_bands(instrument_id, timeframe, from_ts=None, to_ts=None, period=None, stddev_multiplier=None, price_field=None, use_cache=None, max_age_seconds=None, **_extra):
    import json, os, datetime, re, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    if not isinstance(instrument_id, str) or not re.match(r"^grw_ins_[0-9A-Z]{18,}$", instrument_id):
        return _err("VALIDATION_ERROR", "Invalid instrument_id.")
    allowed_tf = {"1min", "5min", "10min", "1hr", "4hr", "daily", "weekly"}
    if timeframe not in allowed_tf:
        return _err("VALIDATION_ERROR", "Invalid timeframe.")
    if not isinstance(period, int) or period < 1:
        return _err("VALIDATION_ERROR", "period must be an integer >= 1.")
    if not isinstance(stddev_multiplier, (int, float)) or float(stddev_multiplier) < 0:
        return _err("VALIDATION_ERROR", "stddev_multiplier must be a number >= 0.")
    if price_field is not None and price_field not in {"close", "open", "high", "low"}:
        return _err("VALIDATION_ERROR", "Invalid price_field.")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.")
    if max_age_seconds is not None and (not isinstance(max_age_seconds, int) or max_age_seconds < 0):
        return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0.")
    if from_ts is not None and not isinstance(from_ts, str):
        return _err("VALIDATION_ERROR", "from_ts must be an ISO 8601 string.")
    if to_ts is not None and not isinstance(to_ts, str):
        return _err("VALIDATION_ERROR", "to_ts must be an ISO 8601 string.")
    if price_field is None:
        price_field = "close"
    if use_cache is None:
        use_cache = True
    if max_age_seconds is None:
        max_age_seconds = 0

    def _parse_dt(s):
        if s is None:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    fdt = _parse_dt(from_ts)
    tdt = _parse_dt(to_ts)
    if (from_ts is not None and fdt is None) or (to_ts is not None and tdt is None):
        return _err("VALIDATION_ERROR", "from_ts/to_ts must be valid ISO 8601 date-time strings.")
    if fdt is not None and tdt is not None and fdt > tdt:
        return _err("VALIDATION_ERROR", "from_ts must be <= to_ts.")

    instruments = _load("instruments.json")
    if not any(r.get("id") == instrument_id for r in instruments):
        return _err("NOT_FOUND", "Instrument not found.", instrument_id=instrument_id)

    # Default window
    if fdt is None or tdt is None:
        tf_seconds = {"1min": 60, "5min": 300, "10min": 600, "1hr": 3600, "4hr": 14400, "daily": 86400, "weekly": 604800}[timeframe]
        tdt = now
        fdt = now - datetime.timedelta(seconds=tf_seconds * 500)

    cache = _load("market_data_cache.json")

    def _is_fresh(row):
        as_of = _parse_dt(row.get("as_of"))
        ttl = row.get("ttl_seconds")
        if as_of is None or not isinstance(ttl, int) or ttl < 0:
            return False
        return row.get("status") == "fresh" and (now - as_of).total_seconds() <= ttl

    def _age_ok(row):
        as_of = _parse_dt(row.get("as_of"))
        if as_of is None:
            return False
        return (now - as_of).total_seconds() <= max_age_seconds

    # Find or create candles cache
    hist_matches = [r for r in cache if r.get("instrument_id") == instrument_id and r.get("data_type") == "historical_candles"
                    and r.get("timeframe") == timeframe and r.get("from_ts") == fdt.isoformat() and r.get("to_ts") == tdt.isoformat()
                    and r.get("max_points") is None]
    hist_matches.sort(key=lambda r: _parse_dt(r.get("as_of")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), reverse=True)

    candles_entry = None
    if use_cache:
        for r in hist_matches:
            if _is_fresh(r) and _age_ok(r):
                candles_entry = r
                break

    if candles_entry is None:
        # generate candles inline with timeframe constraints
        days_limits = {"1min": 3, "5min": 15, "10min": 30, "1hr": 150, "4hr": 365, "daily": 1080, "weekly": None}
        max_days = days_limits[timeframe]
        delta_days = (tdt - fdt).total_seconds() / 86400.0
        if max_days is not None and delta_days > max_days + 1e-9:
            return _err("VALIDATION_ERROR", "Requested date range exceeds timeframe limits.", timeframe=timeframe, max_days=max_days)

        import random
        tf_seconds = {"1min": 60, "5min": 300, "10min": 600, "1hr": 3600, "4hr": 14400, "daily": 86400, "weekly": 604800}[timeframe]
        total_points = max(0, min(int((tdt - fdt).total_seconds() // tf_seconds), 50000))
        seed_material = f"{instrument_id}|{timeframe}|{fdt.isoformat()}|{tdt.isoformat()}|None".encode("utf-8")
        seed = int(hashlib.sha256(seed_material).hexdigest()[:16], 16)
        rng = random.Random(seed)
        base = 50.0 + (seed % 5000) / 100.0
        last_close = base
        candles = []
        for i in range(total_points):
            ts = fdt + datetime.timedelta(seconds=tf_seconds * i)
            drift = (rng.random() - 0.5) * (0.6 if timeframe in {"1min", "5min", "10min"} else 1.5)
            o = max(0.01, last_close + drift)
            h = o + abs(rng.random() * 0.8)
            l = max(0.01, o - abs(rng.random() * 0.8))
            c = max(0.01, l + (h - l) * rng.random())
            v = int(100 + rng.random() * 10000)
            candles.append({"ts": ts.isoformat(), "open": round(o, 4), "high": round(h, 4), "low": round(l, 4), "close": round(c, 4), "volume": v})
            last_close = c

        def _new_id(prefix):
            return f"{prefix}{hashlib.sha256((prefix+now_iso+str(rng.random())).encode('utf-8')).hexdigest()[:24]}"
        candles_entry = {
            "id": _new_id("grw_mdc_"),
            "instrument_id": instrument_id,
            "data_type": "historical_candles",
            "timeframe": timeframe,
            "from_ts": fdt.isoformat(),
            "to_ts": tdt.isoformat(),
            "max_points": None,
            "derived_from_cache_id": None,
            "algorithm": None,
            "parameters": None,
            "as_of": now_iso,
            "ttl_seconds": 3600,
            "status": "fresh",
            "payload": {"candles": candles},
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        cache = _load("market_data_cache.json")
        cache.append(candles_entry)
        _save("market_data_cache.json", cache)

    # Indicator cache lookup
    cache = _load("market_data_cache.json")
    params = {
        "period": period,
        "stddev_multiplier": float(stddev_multiplier),
        "price_field": price_field,
        "from_ts": fdt.isoformat(),
        "to_ts": tdt.isoformat()
    }
    ind_matches = []
    for r in cache:
        if r.get("instrument_id") != instrument_id:
            continue
        if r.get("data_type") != "indicator_result":
            continue
        if r.get("timeframe") != timeframe:
            continue
        if r.get("algorithm") != "bollinger_bands":
            continue
        if r.get("from_ts") != fdt.isoformat() or r.get("to_ts") != tdt.isoformat():
            continue
        if r.get("derived_from_cache_id") != candles_entry.get("id"):
            continue
        if r.get("parameters") != params:
            continue
        ind_matches.append(r)

    ind_matches.sort(key=lambda r: _parse_dt(r.get("as_of")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), reverse=True)
    if use_cache and ind_matches:
        for r in ind_matches:
            if _is_fresh(r) and _age_ok(r):
                latency_ms = int((time.time() - t0) * 1000)
                return {
                    "instrument_id": instrument_id,
                    "timeframe": timeframe,
                    "from_ts": fdt.isoformat(),
                    "to_ts": tdt.isoformat(),
                    "algorithm": "bollinger_bands",
                    "parameters": r.get("parameters"),
                    "source": "cache",
                    "as_of": r.get("as_of"),
                    "ttl_seconds": r.get("ttl_seconds"),
                    "result": r.get("payload"),
                    "meta": {"latency_ms": latency_ms, "cache_id": r.get("id"), "derived_from_cache_id": r.get("derived_from_cache_id")}
                }

    candles = (candles_entry.get("payload") or {}).get("candles", [])
    times, prices = [], []
    for c in candles:
        if isinstance(c, dict) and "ts" in c and price_field in c and isinstance(c.get(price_field), (int, float)):
            times.append(c["ts"])
            prices.append(float(c[price_field]))

    n = len(prices)
    if n < period:
        err_msg = "Insufficient candle data to compute Bollinger Bands."
        def _new_id(prefix):
            return f"{prefix}{hashlib.sha256((prefix+now_iso+'bb').encode('utf-8')).hexdigest()[:24]}"
        entry = {
            "id": _new_id("grw_mdc_"),
            "instrument_id": instrument_id,
            "data_type": "indicator_result",
            "timeframe": timeframe,
            "from_ts": fdt.isoformat(),
            "to_ts": tdt.isoformat(),
            "max_points": None,
            "derived_from_cache_id": candles_entry.get("id"),
            "algorithm": "bollinger_bands",
            "parameters": params,
            "as_of": now_iso,
            "ttl_seconds": 300,
            "status": "failed",
            "payload": None,
            "error_message": err_msg,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        cache = _load("market_data_cache.json")
        cache.append(entry)
        _save("market_data_cache.json", cache)
        return _err("VALIDATION_ERROR", err_msg)

    mult = float(stddev_multiplier)

    series = []
    # rolling sum and sumsq for variance
    s = 0.0
    ss = 0.0
    for i in range(n):
        x = prices[i]
        s += x
        ss += x * x
        if i >= period:
            x0 = prices[i - period]
            s -= x0
            ss -= x0 * x0
        if i >= period - 1:
            mean = s / period
            var = max(0.0, (ss / period) - (mean * mean))
            sd = math.sqrt(var)
            upper = mean + mult * sd
            lower = mean - mult * sd
            series.append({
                "ts": times[i],
                "middle": round(mean, 6),
                "upper": round(upper, 6),
                "lower": round(lower, 6)
            })
        else:
            series.append({"ts": times[i], "middle": None, "upper": None, "lower": None})

    payload = {"series": series, "price_field": price_field}

    def _new_id(prefix):
        return f"{prefix}{hashlib.sha256((prefix+now_iso+'bollinger_bands'+instrument_id).encode('utf-8')).hexdigest()[:24]}"
    entry = {
        "id": _new_id("grw_mdc_"),
        "instrument_id": instrument_id,
        "data_type": "indicator_result",
        "timeframe": timeframe,
        "from_ts": fdt.isoformat(),
        "to_ts": tdt.isoformat(),
        "max_points": None,
        "derived_from_cache_id": candles_entry.get("id"),
        "algorithm": "bollinger_bands",
        "parameters": params,
        "as_of": now_iso,
        "ttl_seconds": 3600,
        "status": "fresh",
        "payload": payload,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    cache = _load("market_data_cache.json")
    cache.append(entry)
    _save("market_data_cache.json", cache)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "instrument_id": instrument_id,
        "timeframe": timeframe,
        "from_ts": fdt.isoformat(),
        "to_ts": tdt.isoformat(),
        "algorithm": "bollinger_bands",
        "parameters": params,
        "source": "upstream",
        "as_of": entry["as_of"],
        "ttl_seconds": entry["ttl_seconds"],
        "result": payload,
        "meta": {"latency_ms": latency_ms, "cache_id": entry["id"], "derived_from_cache_id": entry["derived_from_cache_id"]}
    }

def calculate_support_resistance(instrument_id, timeframe, from_ts=None, to_ts=None, max_points=None, method=None, lookback=None, min_touches=None, merge_threshold_pct=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time")

    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(raw).hexdigest()[:26].upper()}"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "calculate_support_resistance",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(instrument_id, str) or not instrument_id.strip().startswith("grw_ins_"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instrument_id must be a non-empty Groww instrument id string")
    instrument_id = instrument_id.strip()

    allowed_tf = {"1min", "5min", "10min", "1hr", "4hr", "daily", "weekly"}
    if timeframe not in allowed_tf:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "timeframe is invalid", allowed=sorted(allowed_tf))

    fdt, e = _parse_dt(from_ts, "from_ts")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    tdt, e = _parse_dt(to_ts, "to_ts")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    if fdt and tdt and fdt > tdt:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from_ts must be <= to_ts")

    if max_points is not None:
        if not isinstance(max_points, int) or max_points < 10:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "max_points must be an integer >= 10")
    else:
        max_points = 500

    if method is not None and method not in {"pivot", "swing", "fractal"}:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "method must be one of ['pivot','swing','fractal']")
    if method is None:
        method = "pivot"

    if lookback is not None and (not isinstance(lookback, int) or lookback < 2):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "lookback must be an integer >= 2")
    if lookback is None:
        lookback = 10

    if min_touches is not None and (not isinstance(min_touches, int) or min_touches < 1):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "min_touches must be an integer >= 1")
    if min_touches is None:
        min_touches = 2

    if merge_threshold_pct is not None:
        if not isinstance(merge_threshold_pct, (int, float)) or isinstance(merge_threshold_pct, bool) or not math.isfinite(float(merge_threshold_pct)) or float(merge_threshold_pct) < 0:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "merge_threshold_pct must be a number >= 0")
    else:
        merge_threshold_pct = 0.25

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    if not any(isinstance(r, dict) and r.get("id") == instrument_id for r in instruments):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Instrument not found", instrument_id=instrument_id)

    cache = _load("market_data_cache.json")
    if not isinstance(cache, list):
        cache = []

    now = _now_utc()

    # Ensure candle input cache exists (reuse logic similar to moving averages)
    hist_row = None
    hist_candidates = []
    for r in cache:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != instrument_id:
            continue
        if r.get("data_type") != "historical_candles":
            continue
        if r.get("timeframe") != timeframe:
            continue
        if (from_ts is None and r.get("from_ts") is not None) or (from_ts is not None and r.get("from_ts") != from_ts):
            continue
        if (to_ts is None and r.get("to_ts") is not None) or (to_ts is not None and r.get("to_ts") != to_ts):
            continue
        if r.get("status") != "fresh":
            continue
        hist_candidates.append(r)

    if hist_candidates:
        def _asof_key(rr):
            dt, _ = _parse_dt(rr.get("as_of"), "as_of")
            return dt or datetime.datetime.fromtimestamp(0, datetime.timezone.utc)
        hist_candidates.sort(key=_asof_key, reverse=True)
        hist_row = hist_candidates[0]
    else:
        # create synthetic candles
        n = max_points
        base = 100.0
        candles = []
        for i in range(n):
            h = hashlib.sha256(f"{instrument_id}:{timeframe}:sr:{i}".encode("utf-8")).digest()
            delta = (h[0] - 128) / 1280.0
            op = base + delta
            hi = op + abs((h[1] - 128) / 384.0)
            lo = op - abs((h[2] - 128) / 384.0)
            cl = lo + (hi - lo) * (h[3] / 255.0)
            base = cl
            ts = now - datetime.timedelta(minutes=(n - 1 - i))
            candles.append({"t": _iso(ts), "open": op, "high": hi, "low": lo, "close": cl})
        now_iso = _iso(now)
        hist_row = {
            "id": _gen_id("grw_mdc"),
            "instrument_id": instrument_id,
            "data_type": "historical_candles",
            "timeframe": timeframe,
            "from_ts": from_ts,
            "to_ts": to_ts,
            "max_points": n,
            "derived_from_cache_id": None,
            "algorithm": None,
            "parameters": None,
            "as_of": now_iso,
            "ttl_seconds": 60,
            "status": "fresh",
            "payload": {"candles": candles},
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        cache.append(hist_row)
        _save("market_data_cache.json", cache)

    candles = (hist_row.get("payload") or {}).get("candles") if isinstance(hist_row.get("payload"), dict) else None
    if not isinstance(candles, list) or len(candles) < 10:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No candle data available", derived_from_cache_id=hist_row.get("id"))

    # Truncate to max_points (most recent)
    candles = candles[-max_points:]

    highs = []
    lows = []
    times = []
    for c in candles:
        if not isinstance(c, dict):
            continue
        h = c.get("high")
        l = c.get("low")
        if not isinstance(h, (int, float)) or not isinstance(l, (int, float)):
            continue
        highs.append(float(h))
        lows.append(float(l))
        times.append(c.get("t"))

    if len(highs) < lookback * 2:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Not enough candles for lookback", available=len(highs), lookback=lookback)

    # Simple pivot detection: local extrema in lookback window
    pivots_hi = []
    pivots_lo = []
    for i in range(lookback, len(highs) - lookback):
        window_hi = highs[i - lookback:i + lookback + 1]
        window_lo = lows[i - lookback:i + lookback + 1]
        if highs[i] == max(window_hi):
            pivots_hi.append(highs[i])
        if lows[i] == min(window_lo):
            pivots_lo.append(lows[i])

    def _merge_levels(levels, pct):
        levels = sorted(levels)
        merged = []
        for lv in levels:
            if not merged:
                merged.append({"level": lv, "touches": 1})
                continue
            last = merged[-1]["level"]
            thresh = abs(last) * (pct / 100.0)
            if abs(lv - last) <= thresh:
                # merge by averaging
                merged[-1]["level"] = (merged[-1]["level"] * merged[-1]["touches"] + lv) / (merged[-1]["touches"] + 1)
                merged[-1]["touches"] += 1
            else:
                merged.append({"level": lv, "touches": 1})
        return [m for m in merged if m["touches"] >= min_touches]

    supports = _merge_levels(pivots_lo, float(merge_threshold_pct))
    resistances = _merge_levels(pivots_hi, float(merge_threshold_pct))

    result_payload = {
        "method": method,
        "lookback": lookback,
        "min_touches": min_touches,
        "merge_threshold_pct": float(merge_threshold_pct),
        "supports": supports,
        "resistances": resistances,
        "derived_from_cache_id": hist_row.get("id"),
        "points_used": len(candles),
        "as_of": _iso(now),
    }

    # Store indicator result
    params = {
        "method": method,
        "lookback": lookback,
        "min_touches": min_touches,
        "merge_threshold_pct": float(merge_threshold_pct),
        "max_points": max_points,
        "from_ts": from_ts,
        "to_ts": to_ts,
        "timeframe": timeframe
    }
    now_iso = _iso(now)
    ind_row = {
        "id": _gen_id("grw_mdc"),
        "instrument_id": instrument_id,
        "data_type": "indicator_result",
        "timeframe": timeframe,
        "from_ts": from_ts,
        "to_ts": to_ts,
        "max_points": max_points,
        "derived_from_cache_id": hist_row.get("id"),
        "algorithm": "support_resistance",
        "parameters": params,
        "as_of": now_iso,
        "ttl_seconds": 60,
        "status": "fresh",
        "payload": result_payload,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    cache.append(ind_row)
    _save("market_data_cache.json", cache)

    _log("success")
    return {"instrument_id": instrument_id, "timeframe": timeframe, "result": result_payload, "cache_id": ind_row["id"]}

def calculate_volatility_metrics(instrument_id, timeframe, from_ts=None, to_ts=None, max_points=None, window=None, metrics=None, annualize=None, **_extra):
    import json, os, datetime, time, hashlib, random, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time", field=field)

    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}:{random.random()}".encode("utf-8")
        return f"{prefix}_01{hashlib.sha256(raw).hexdigest()[:24].upper()}"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "calculate_volatility_metrics",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(instrument_id, str) or not instrument_id.strip() or not instrument_id.startswith("grw_ins_"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instrument_id must be a non-empty string starting with 'grw_ins_'", field="instrument_id")

    allowed_tf = {"1min", "5min", "10min", "1hr", "4hr", "daily", "weekly"}
    if not isinstance(timeframe, str) or timeframe not in allowed_tf:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "timeframe must be one of the supported values", field="timeframe", allowed=sorted(allowed_tf))

    fdt, e = _parse_dt(from_ts, "from_ts")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    tdt, e = _parse_dt(to_ts, "to_ts")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    if fdt and tdt and fdt > tdt:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from_ts must be <= to_ts", field="from_ts")

    if max_points is None:
        max_points = 500
    if not isinstance(max_points, int) or isinstance(max_points, bool) or max_points < 10:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max_points must be an integer >= 10", field="max_points")

    if window is None:
        window = 14
    if not isinstance(window, int) or isinstance(window, bool) or window < 2:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "window must be an integer >= 2", field="window")

    supported_metrics = {"returns_std", "atr", "true_range", "parkinson", "garman_klass", "yang_zhang", "donchian_width"}
    if metrics is None:
        metrics = ["returns_std"]
    if not isinstance(metrics, list) or len(metrics) < 1 or any((not isinstance(m, str) or m not in supported_metrics) for m in metrics):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "metrics must be a non-empty array of supported metric names", field="metrics", supported=sorted(supported_metrics))

    if annualize is None:
        annualize = False
    if not isinstance(annualize, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "annualize must be a boolean", field="annualize")

    # Ensure instrument exists
    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    if not any(isinstance(r, dict) and r.get("id") == instrument_id for r in instruments):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Instrument not found", instrument_id=instrument_id)

    cache = _load("market_data_cache.json")
    if not isinstance(cache, list):
        cache = []

    now = _now_utc()
    # Candle source: get/create historical cache for window
    if fdt is None:
        tdt_eff = tdt or now
        fdt_eff = tdt_eff - datetime.timedelta(days=7)
    else:
        fdt_eff = fdt
        tdt_eff = tdt or now

    # Create candles (same deterministic generator as other tools)
    step = {"1min": 60, "5min": 300, "10min": 600, "1hr": 3600, "4hr": 14400, "daily": 86400, "weekly": 604800}[timeframe]
    total_secs = max(0, int((tdt_eff - fdt_eff).total_seconds()))
    points = max(0, total_secs // step)
    points = min(points, max_points, 50000)

    seed = int(hashlib.sha256(f"{instrument_id}:{timeframe}".encode("utf-8")).hexdigest()[:8], 16)
    base = 100 + (seed % 5000) / 10.0

    candles = []
    for i in range(points):
        drift = math.sin((seed % 1000 + i) / 17.0) * 0.8
        close = base + drift + (i * 0.01)
        open_ = close - 0.2
        high = close + 0.5
        low = close - 0.6
        candles.append({"open": open_, "high": high, "low": low, "close": close})

    # Compute metrics
    closes = [c["close"] for c in candles]
    highs = [c["high"] for c in candles]
    lows = [c["low"] for c in candles]
    opens = [c["open"] for c in candles]

    def _rolling_std(returns, w):
        out = [None] * len(returns)
        for i in range(len(returns)):
            if i < w - 1:
                continue
            seg = returns[i - w + 1:i + 1]
            mu = sum(seg) / w
            var = sum((x - mu) ** 2 for x in seg) / w
            out[i] = math.sqrt(var)
        return out

    returns = [None] * len(closes)
    for i in range(1, len(closes)):
        if closes[i - 1] != 0:
            returns[i] = math.log(closes[i] / closes[i - 1])
    ret_series = [r for r in returns if r is not None]
    ann_factor = 252.0 if timeframe in {"daily", "weekly"} else 252.0 * (6.5 * 60 * 60) / float(step)

    outputs = {}
    if "returns_std" in metrics:
        rs = _rolling_std([r if r is not None else 0.0 for r in returns], window)
        val = rs[-1] if rs else None
        if annualize and val is not None:
            val = val * math.sqrt(ann_factor)
        outputs["returns_std"] = val

    def _true_range(i):
        if i == 0:
            return highs[i] - lows[i]
        return max(highs[i] - lows[i], abs(highs[i] - closes[i - 1]), abs(lows[i] - closes[i - 1]))

    if "true_range" in metrics or "atr" in metrics:
        tr = [(_true_range(i) if i < len(highs) else None) for i in range(len(highs))]
        outputs["true_range"] = tr[-1] if tr else None
        if "atr" in metrics:
            # simple moving average of TR over window
            atr = None
            if len(tr) >= window:
                atr = sum(tr[-window:]) / float(window)
            outputs["atr"] = atr

    if "parkinson" in metrics:
        # Parkinson volatility estimator (single window last)
        pk = None
        if len(highs) >= window:
            seg = [(math.log(highs[i] / lows[i])) ** 2 for i in range(len(highs) - window, len(highs))]
            denom = 4.0 * window * math.log(2.0)
            pk = math.sqrt(sum(seg) / denom) if denom > 0 else None
            if annualize and pk is not None:
                pk = pk * math.sqrt(ann_factor)
        outputs["parkinson"] = pk

    if "garman_klass" in metrics:
        gk = None
        if len(highs) >= window:
            seg = []
            for i in range(len(highs) - window, len(highs)):
                hl = math.log(highs[i] / lows[i])
                co = math.log(closes[i] / opens[i]) if opens[i] != 0 else 0.0
                seg.append(0.5 * hl * hl - (2 * math.log(2) - 1) * co * co)
            gk = math.sqrt(max(0.0, sum(seg) / window))
            if annualize and gk is not None:
                gk = gk * math.sqrt(ann_factor)
        outputs["garman_klass"] = gk

    if "yang_zhang" in metrics:
        yz = None
        if len(highs) >= window + 1:
            # simplified YZ: combine overnight/open-close and intraday vol
            oc = [math.log(opens[i] / closes[i - 1]) if i > 0 and closes[i - 1] != 0 else 0.0 for i in range(len(opens))]
            co = [math.log(closes[i] / opens[i]) if opens[i] != 0 else 0.0 for i in range(len(opens))]
            rs = [math.log(highs[i] / opens[i]) * math.log(highs[i] / closes[i]) + math.log(lows[i] / opens[i]) * math.log(lows[i] / closes[i]) for i in range(len(opens))]
            oc_seg = oc[-window:]
            co_seg = co[-window:]
            rs_seg = rs[-window:]
            def _var(seg):
                mu = sum(seg) / len(seg)
                return sum((x - mu) ** 2 for x in seg) / len(seg)
            k = 0.34 / (1.34 + (window + 1.0) / (window - 1.0))
            yz = math.sqrt(max(0.0, _var(oc_seg) + k * _var(co_seg) + (1 - k) * (sum(rs_seg) / window)))
            if annualize and yz is not None:
                yz = yz * math.sqrt(ann_factor)
        outputs["yang_zhang"] = yz

    if "donchian_width" in metrics:
        dw = None
        if len(highs) >= window:
            hi = max(highs[-window:])
            lo = min(lows[-window:])
            mid = (hi + lo) / 2.0
            dw = ((hi - lo) / mid) if mid != 0 else None
        outputs["donchian_width"] = dw

    params = {"window": window, "metrics": metrics, "annualize": annualize, "from_ts": _iso(fdt_eff), "to_ts": _iso(tdt_eff), "max_points": max_points}
    entry = {
        "id": _gen_id("grw_mdc"),
        "instrument_id": instrument_id,
        "data_type": "indicator_result",
        "timeframe": timeframe,
        "from_ts": _iso(fdt_eff),
        "to_ts": _iso(tdt_eff),
        "max_points": max_points,
        "derived_from_cache_id": None,
        "algorithm": "volatility_metrics",
        "parameters": params,
        "as_of": _iso(now),
        "ttl_seconds": 3600,
        "status": "fresh",
        "payload": {"metrics": outputs, "parameters": params},
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    cache.append(entry)
    _save("market_data_cache.json", cache)

    _log("ok", meta={"cache_id": entry["id"], "metrics": metrics})
    return {"instrument_id": instrument_id, "timeframe": timeframe, "as_of": entry["as_of"], "result": entry["payload"], "cache_id": entry["id"]}

def calculate_macd(instrument_id, timeframe, from_ts=None, to_ts=None, max_points=None, fast_period=None, slow_period=None, signal_period=None, price_field=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
