    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time")

    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(raw).hexdigest()[:26].upper()}"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "calculate_macd",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(instrument_id, str) or not instrument_id.strip().startswith("grw_ins_"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instrument_id must be a non-empty Groww instrument id string")
    instrument_id = instrument_id.strip()

    allowed_tf = {"1min", "5min", "10min", "1hr", "4hr", "daily", "weekly"}
    if timeframe not in allowed_tf:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "timeframe is invalid", allowed=sorted(allowed_tf))

    fdt, e = _parse_dt(from_ts, "from_ts")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    tdt, e = _parse_dt(to_ts, "to_ts")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    if fdt and tdt and fdt > tdt:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from_ts must be <= to_ts")

    if max_points is not None and (not isinstance(max_points, int) or max_points < 10):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max_points must be an integer >= 10")
    if max_points is None:
        max_points = 500

    if fast_period is not None and (not isinstance(fast_period, int) or fast_period < 1):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fast_period must be an integer >= 1")
    if slow_period is not None and (not isinstance(slow_period, int) or slow_period < 2):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "slow_period must be an integer >= 2")
    if signal_period is not None and (not isinstance(signal_period, int) or signal_period < 1):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "signal_period must be an integer >= 1")

    if fast_period is None:
        fast_period = 12
    if slow_period is None:
        slow_period = 26
    if signal_period is None:
        signal_period = 9

    if fast_period >= slow_period:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fast_period must be < slow_period")

    if price_field is None:
        price_field = "close"
    if price_field not in {"close", "hlc3", "ohlc4"}:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "price_field is invalid", allowed=["close", "hlc3", "ohlc4"])

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    if not any(isinstance(r, dict) and r.get("id") == instrument_id for r in instruments):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Instrument not found", instrument_id=instrument_id)

    cache = _load("market_data_cache.json")
    if not isinstance(cache, list):
        cache = []

    now = _now_utc()

    # Ensure historical candles
    hist_row = None
    for r in cache:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != instrument_id:
            continue
        if r.get("data_type") != "historical_candles":
            continue
        if r.get("timeframe") != timeframe:
            continue
        if r.get("status") != "fresh":
            continue
        hist_row = r
        break
    if hist_row is None:
        n = max_points
        base = 100.0
        candles = []
        for i in range(n):
            h = hashlib.sha256(f"{instrument_id}:{timeframe}:macd:{i}".encode("utf-8")).digest()
            delta = (h[0] - 128) / 1280.0
            op = base + delta
            hi = op + abs((h[1] - 128) / 384.0)
            lo = op - abs((h[2] - 128) / 384.0)
            cl = lo + (hi - lo) * (h[3] / 255.0)
            base = cl
            ts = now - datetime.timedelta(minutes=(n - 1 - i))
            candles.append({"t": _iso(ts), "open": op, "high": hi, "low": lo, "close": cl})
        now_iso = _iso(now)
        hist_row = {
            "id": _gen_id("grw_mdc"),
            "instrument_id": instrument_id,
            "data_type": "historical_candles",
            "timeframe": timeframe,
            "from_ts": from_ts,
            "to_ts": to_ts,
            "max_points": n,
            "derived_from_cache_id": None,
            "algorithm": None,
            "parameters": None,
            "as_of": now_iso,
            "ttl_seconds": 60,
            "status": "fresh",
            "payload": {"candles": candles},
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        cache.append(hist_row)
        _save("market_data_cache.json", cache)

    candles = (hist_row.get("payload") or {}).get("candles") if isinstance(hist_row.get("payload"), dict) else None
    if not isinstance(candles, list) or len(candles) < 10:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No candle data available", derived_from_cache_id=hist_row.get("id"))
    candles = candles[-max_points:]

    times, series = [], []
    for c in candles:
        if not isinstance(c, dict):
            continue
        try:
            o = float(c["open"]); h = float(c["high"]); l = float(c["low"]); cl = float(c["close"])
            if price_field == "close":
                px = cl
            elif price_field == "hlc3":
                px = (h + l + cl) / 3.0
            else:
                px = (o + h + l + cl) / 4.0
            series.append(px)
            times.append(c.get("t"))
        except Exception:
            continue

    if len(series) < slow_period + signal_period:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Not enough candles for MACD periods", available=len(series), slow_period=slow_period, signal_period=signal_period)

    def _ema(series, period):
        out = [None] * len(series)
        k = 2.0 / (period + 1.0)
        ema = None
        for i, v in enumerate(series):
            if ema is None:
                if i >= period - 1:
                    ema = sum(series[i - period + 1:i + 1]) / period
                    out[i] = ema
            else:
                ema = (v - ema) * k + ema
                out[i] = ema
        return out

    ema_fast = _ema(series, fast_period)
    ema_slow = _ema(series, slow_period)

    macd_line = [None] * len(series)
    for i in range(len(series)):
        if ema_fast[i] is None or ema_slow[i] is None:
            continue
        macd_line[i] = ema_fast[i] - ema_slow[i]

    # signal EMA on macd_line (skip None by starting where defined)
    macd_defined = [v for v in macd_line if v is not None]
    if len(macd_defined) < signal_period:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Not enough MACD points for signal period", available=len(macd_defined), signal_period=signal_period)

    # compute EMA over macd_line keeping alignment
    # build compact then map back
    compact_idx = [i for i, v in enumerate(macd_line) if v is not None]
    compact_vals = [macd_line[i] for i in compact_idx]
    compact_sig = _ema(compact_vals, signal_period)
    signal_line = [None] * len(series)
    for j, i in enumerate(compact_idx):
        signal_line[i] = compact_sig[j]

    hist = [None] * len(series)
    for i in range(len(series)):
        if macd_line[i] is None or signal_line[i] is None:
            continue
        hist[i] = macd_line[i] - signal_line[i]

    result_payload = {
        "timestamps": times,
        "price_field": price_field,
        "fast_period": fast_period,
        "slow_period": slow_period,
        "signal_period": signal_period,
        "macd": macd_line,
        "signal": signal_line,
        "histogram": hist
    }

    params = {"fast_period": fast_period, "slow_period": slow_period, "signal_period": signal_period, "price_field": price_field, "max_points": max_points, "from_ts": from_ts, "to_ts": to_ts, "timeframe": timeframe}
    now_iso = _iso(now)
    ind_row = {
        "id": _gen_id("grw_mdc"),
        "instrument_id": instrument_id,
        "data_type": "indicator_result",
        "timeframe": timeframe,
        "from_ts": from_ts,
        "to_ts": to_ts,
        "max_points": max_points,
        "derived_from_cache_id": hist_row.get("id"),
        "algorithm": "macd",
        "parameters": params,
        "as_of": now_iso,
        "ttl_seconds": 60,
        "status": "fresh",
        "payload": result_payload,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    cache.append(ind_row)
    _save("market_data_cache.json", cache)

    _log("success")
    return {"instrument_id": instrument_id, "timeframe": timeframe, "result": result_payload, "cache_id": ind_row["id"], "derived_from_cache_id": hist_row.get("id")}

