        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "k_period must be an integer >= 1")
    if not isinstance(k_smoothing, int) or k_smoothing < 1:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "k_smoothing must be an integer >= 1")
