        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "d_period must be an integer >= 1")
    if ma_type not in {"sma", "ema"}:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "ma_type must be 'sma' or 'ema'")

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    if not any(isinstance(r, dict) and r.get("id") == instrument_id for r in instruments):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Instrument not found", instrument_id=instrument_id)

    cache = _load("market_data_cache.json")
    if not isinstance(cache, list):
        cache = []
    now = _now_utc()

    # ensure candles
    hist_row = None
    for r in cache:
        if isinstance(r, dict) and r.get("instrument_id") == instrument_id and r.get("data_type") == "historical_candles" and r.get("timeframe") == timeframe and r.get("status") == "fresh":
            hist_row = r
            break
    if hist_row is None:
        n = max_points
        base = 100.0
        candles = []
        for i in range(n):
            h = hashlib.sha256(f"{instrument_id}:{timeframe}:stoch:{i}".encode("utf-8")).digest()
            delta = (h[0] - 128) / 1280.0
            op = base + delta
            hi = op + abs((h[1] - 128) / 384.0)
            lo = op - abs((h[2] - 128) / 384.0)
            cl = lo + (hi - lo) * (h[3] / 255.0)
            base = cl
            ts = now - datetime.timedelta(minutes=(n - 1 - i))
            candles.append({"t": _iso(ts), "open": op, "high": hi, "low": lo, "close": cl})
        now_iso = _iso(now)
        hist_row = {
            "id": _gen_id("grw_mdc"),
            "instrument_id": instrument_id,
            "data_type": "historical_candles",
            "timeframe": timeframe,
            "from_ts": from_ts,
            "to_ts": to_ts,
            "max_points": n,
            "derived_from_cache_id": None,
            "algorithm": None,
            "parameters": None,
            "as_of": now_iso,
            "ttl_seconds": 60,
            "status": "fresh",
            "payload": {"candles": candles},
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        cache.append(hist_row)
        _save("market_data_cache.json", cache)

    candles = (hist_row.get("payload") or {}).get("candles") if isinstance(hist_row.get("payload"), dict) else None
    if not isinstance(candles, list) or len(candles) < k_period:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Not enough candles for k_period", available=len(candles) if isinstance(candles, list) else 0, k_period=k_period)
    candles = candles[-max_points:]

    H, L, C, T = [], [], [], []
    for c in candles:
        if not isinstance(c, dict):
            continue
        try:
            H.append(float(c["high"]))
            L.append(float(c["low"]))
            C.append(float(c["close"]))
            T.append(c.get("t"))
        except Exception:
            continue

    n = len(C)
    k_raw = [None] * n
    for i in range(k_period - 1, n):
        hh = max(H[i - k_period + 1:i + 1])
        ll = min(L[i - k_period + 1:i + 1])
        denom = (hh - ll)
        k_raw[i] = 0.0 if denom == 0 else 100.0 * (C[i] - ll) / denom

    def _sma(arr, p):
        out = [None] * len(arr)
        s = 0.0
        cnt = 0
        for i, v in enumerate(arr):
            if v is None:
                continue
            s += v
            cnt += 1
            # manage window by looking back p and subtract if defined
            if i - p >= 0 and arr[i - p] is not None:
                s -= arr[i - p]
                cnt -= 1
            if i >= 0 and cnt == p:
                out[i] = s / p
        return out

    def _ema_defined(values, p):
        out = [None] * len(values)
        k = 2.0 / (p + 1.0)
        ema = None
        for i, v in enumerate(values):
            if v is None:
                continue
            if ema is None:
                # seed with SMA of first p defined values ending at i
                defined = []
                for j in range(max(0, i - p + 1), i + 1):
                    if values[j] is not None:
                        defined.append(values[j])
                if len(defined) == p:
                    ema = sum(defined) / p
                    out[i] = ema
            else:
                ema = (v - ema) * k + ema
                out[i] = ema
        return out

    if ma_type == "sma":
        k_smooth = _sma(k_raw, k_smoothing)
        d_line = _sma(k_smooth, d_period)
    else:
        k_smooth = _ema_defined(k_raw, k_smoothing)
        d_line = _ema_defined(k_smooth, d_period)

    result_payload = {
        "timestamps": T,
        "k_period": k_period,
        "k_smoothing": k_smoothing,
        "d_period": d_period,
        "ma_type": ma_type,
        "percent_k": k_smooth,
        "percent_d": d_line
    }

    params = {"k_period": k_period, "k_smoothing": k_smoothing, "d_period": d_period, "ma_type": ma_type, "max_points": max_points, "from_ts": from_ts, "to_ts": to_ts, "timeframe": timeframe}
    now_iso = _iso(now)
    ind_row = {
        "id": _gen_id("grw_mdc"),
        "instrument_id": instrument_id,
        "data_type": "indicator_result",
        "timeframe": timeframe,
        "from_ts": from_ts,
        "to_ts": to_ts,
        "max_points": max_points,
        "derived_from_cache_id": hist_row.get("id"),
        "algorithm": "stochastic",
        "parameters": params,
        "as_of": now_iso,
        "ttl_seconds": 60,
        "status": "fresh",
        "payload": result_payload,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    cache.append(ind_row)
    _save("market_data_cache.json", cache)

    _log("success")
    return {"instrument_id": instrument_id, "timeframe": timeframe, "result": result_payload, "cache_id": ind_row["id"], "derived_from_cache_id": hist_row.get("id")}

