        return _err("VALIDATION_ERROR", "period must be an integer >= 1")

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    if not any(isinstance(r, dict) and r.get("id") == instrument_id for r in instruments):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Instrument not found", instrument_id=instrument_id)

    cache = _load("market_data_cache.json")
    if not isinstance(cache, list):
        cache = []
    now = _now_utc()

    # ensure candles
    hist_row = None
    for r in cache:
        if isinstance(r, dict) and r.get("instrument_id") == instrument_id and r.get("data_type") == "historical_candles" and r.get("timeframe") == timeframe and r.get("status") == "fresh":
            hist_row = r
            break
    if hist_row is None:
        n = max_points
        base = 100.0
        candles = []
        for i in range(n):
            h = hashlib.sha256(f"{instrument_id}:{timeframe}:adx:{i}".encode("utf-8")).digest()
            delta = (h[0] - 128) / 1280.0
            op = base + delta
            hi = op + abs((h[1] - 128) / 384.0)
            lo = op - abs((h[2] - 128) / 384.0)
            cl = lo + (hi - lo) * (h[3] / 255.0)
            base = cl
            ts = now - datetime.timedelta(minutes=(n - 1 - i))
            candles.append({"t": _iso(ts), "open": op, "high": hi, "low": lo, "close": cl})
        now_iso = _iso(now)
        hist_row = {
            "id": _gen_id("grw_mdc"),
            "instrument_id": instrument_id,
            "data_type": "historical_candles",
            "timeframe": timeframe,
            "from_ts": from_ts,
            "to_ts": to_ts,
            "max_points": n,
            "derived_from_cache_id": None,
            "algorithm": None,
            "parameters": None,
            "as_of": now_iso,
            "ttl_seconds": 60,
            "status": "fresh",
            "payload": {"candles": candles},
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        cache.append(hist_row)
        _save("market_data_cache.json", cache)

    candles = (hist_row.get("payload") or {}).get("candles") if isinstance(hist_row.get("payload"), dict) else None
    if not isinstance(candles, list) or len(candles) < period + 2:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Not enough candles for ADX period", available=len(candles) if isinstance(candles, list) else 0, period=period)
    candles = candles[-max_points:]

    H, L, C, T = [], [], [], []
    for c in candles:
        if not isinstance(c, dict):
            continue
        try:
            H.append(float(c["high"]))
            L.append(float(c["low"]))
            C.append(float(c["close"]))
            T.append(c.get("t"))
        except Exception:
            continue

    n = len(C)
    tr = [None] * n
    plus_dm = [0.0] * n
    minus_dm = [0.0] * n
    for i in range(1, n):
        up = H[i] - H[i - 1]
        dn = L[i - 1] - L[i]
        plus_dm[i] = up if up > dn and up > 0 else 0.0
        minus_dm[i] = dn if dn > up and dn > 0 else 0.0
        tr[i] = max(H[i] - L[i], abs(H[i] - C[i - 1]), abs(L[i] - C[i - 1]))

    # Wilder smoothing
    def _wilder(vals, p):
        out = [None] * len(vals)
        s = 0.0
        # seed using first p values from index 1..p
        if len(vals) <= p:
            return out
        seed = []
        for i in range(1, p + 1):
            v = vals[i]
            seed.append(0.0 if v is None else float(v))
        s = sum(seed)
        out[p] = s
        for i in range(p + 1, len(vals)):
            v = vals[i]
            v = 0.0 if v is None else float(v)
            s = s - (s / p) + v
            out[i] = s
        return out

    tr_s = _wilder(tr, period)
    pdm_s = _wilder(plus_dm, period)
    mdm_s = _wilder(minus_dm, period)

    plus_di = [None] * n
    minus_di = [None] * n
    dx = [None] * n
    for i in range(n):
        if tr_s[i] is None or tr_s[i] == 0:
            continue
        plus_di[i] = 100.0 * (pdm_s[i] / tr_s[i]) if pdm_s[i] is not None else None
        minus_di[i] = 100.0 * (mdm_s[i] / tr_s[i]) if mdm_s[i] is not None else None
        if plus_di[i] is None or minus_di[i] is None:
            continue
        denom = plus_di[i] + minus_di[i]
        dx[i] = 0.0 if denom == 0 else 100.0 * abs(plus_di[i] - minus_di[i]) / denom

    # ADX is Wilder smoothing of DX
    adx = [None] * n
    # seed: average first period dx values starting at index period..2*period-1 where dx defined
    start = period
    seed_vals = []
    for i in range(start, min(n, start + period)):
        if dx[i] is not None:
            seed_vals.append(dx[i])
    if len(seed_vals) == period:
        adx[start + period - 1] = sum(seed_vals) / period
        prev = adx[start + period - 1]
        for i in range(start + period, n):
            if dx[i] is None:
                continue
            prev = (prev * (period - 1) + dx[i]) / period
            adx[i] = prev

    result_payload = {
        "timestamps": T,
        "period": period,
        "plus_di": plus_di,
        "minus_di": minus_di,
        "adx": adx
    }

    params = {"period": period, "max_points": max_points, "from_ts": from_ts, "to_ts": to_ts, "timeframe": timeframe}
    now_iso = _iso(now)
    ind_row = {
        "id": _gen_id("grw_mdc"),
        "instrument_id": instrument_id,
        "data_type": "indicator_result",
        "timeframe": timeframe,
        "from_ts": from_ts,
        "to_ts": to_ts,
        "max_points": max_points,
        "derived_from_cache_id": hist_row.get("id"),
        "algorithm": "adx",
        "parameters": params,
        "as_of": now_iso,
        "ttl_seconds": 60,
        "status": "fresh",
        "payload": result_payload,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    cache.append(ind_row)
    _save("market_data_cache.json", cache)

    _log("success")
    return {"instrument_id": instrument_id, "timeframe": timeframe, "result": result_payload, "cache_id": ind_row["id"], "derived_from_cache_id": hist_row.get("id")}

