        return _err("NOT_FOUND", "No candle data available", derived_from_cache_id=hist_row.get("id"))
    candles = candles[-max_points:]

    highs = [float(c["high"]) for c in candles if isinstance(c, dict) and isinstance(c.get("high"), (int, float))]
    lows = [float(c["low"]) for c in candles if isinstance(c, dict) and isinstance(c.get("low"), (int, float))]
    if not highs or not lows:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Candle series missing highs/lows", derived_from_cache_id=hist_row.get("id"))

    swing_high = max(highs)
    swing_low = min(lows)
    # If auto: assume swing is low->high (uptrend) unless last close nearer to low
    if swing == "auto":
        last_close = None
        for c in reversed(candles):
            if isinstance(c, dict) and isinstance(c.get("close"), (int, float)):
                last_close = float(c["close"])
                break
        if last_close is not None and abs(last_close - swing_low) < abs(last_close - swing_high):
            direction = "down"
        else:
            direction = "up"
    else:
        direction = "up"

    diff = swing_high - swing_low
    retracements = []
    for r in lvl:
        if direction == "up":
            price = swing_high - diff * r
        else:
            price = swing_low + diff * r
        retracements.append({"ratio": r, "price": price})

    extensions = []
    if include_extensions:
        for r in ext:
            if direction == "up":
                price = swing_high + diff * (r - 1.0)
            else:
                price = swing_low - diff * (r - 1.0)
            extensions.append({"ratio": r, "price": price})

    result_payload = {
        "swing": swing,
        "direction": direction,
        "swing_high": swing_high,
        "swing_low": swing_low,
        "retracements": retracements,
        "extensions": extensions if include_extensions else None,
        "derived_from_cache_id": hist_row.get("id"),
        "as_of": _iso(now)
    }

    params = {"swing": swing, "levels": lvl, "include_extensions": include_extensions, "extension_levels": ext if include_extensions else None, "max_points": max_points, "from_ts": from_ts, "to_ts": to_ts, "timeframe": timeframe}
    now_iso = _iso(now)
    ind_row = {
        "id": _gen_id("grw_mdc"),
        "instrument_id": instrument_id,
        "data_type": "indicator_result",
        "timeframe": timeframe,
        "from_ts": from_ts,
        "to_ts": to_ts,
        "max_points": max_points,
        "derived_from_cache_id": hist_row.get("id"),
        "algorithm": "fibonacci",
        "parameters": params,
        "as_of": now_iso,
        "ttl_seconds": 60,
        "status": "fresh",
        "payload": result_payload,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    cache.append(ind_row)
    _save("market_data_cache.json", cache)

    _log("success")
    return {"instrument_id": instrument_id, "timeframe": timeframe, "result": result_payload, "cache_id": ind_row["id"], "derived_from_cache_id": hist_row.get("id")}

def analyze_candlestick_patterns(instrument_id, timeframe, from_ts=None, to_ts=None, max_points=None, patterns=None, min_confidence=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time")

    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(raw).hexdigest()[:26].upper()}"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "analyze_candlestick_patterns",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(instrument_id, str) or not instrument_id.strip().startswith("grw_ins_"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instrument_id must be a non-empty Groww instrument id string")
    instrument_id = instrument_id.strip()

    allowed_tf = {"1min", "5min", "10min", "1hr", "4hr", "daily", "weekly"}
    if timeframe not in allowed_tf:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "timeframe is invalid", allowed=sorted(allowed_tf))

    fdt, e = _parse_dt(from_ts, "from_ts")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    tdt, e = _parse_dt(to_ts, "to_ts")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    if fdt and tdt and fdt > tdt:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from_ts must be <= to_ts")

    if max_points is not None and (not isinstance(max_points, int) or max_points < 5):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max_points must be an integer >= 5")
    if max_points is None:
        max_points = 200

    supported = {
        "doji", "hammer", "inverted_hammer", "shooting_star", "hanging_man",
        "engulfing_bullish", "engulfing_bearish", "harami_bullish", "harami_bearish",
        "piercing_line", "dark_cloud_cover", "morning_star", "evening_star",
        "three_white_soldiers", "three_black_crows"
    }

    if patterns is not None:
        if not isinstance(patterns, list) or len(patterns) < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "patterns must be a non-empty array when provided")
        for p in patterns:
            if p not in supported:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Unsupported pattern", pattern=p)
        wanted = set(patterns)
    else:
        wanted = {"doji", "hammer", "shooting_star", "engulfing_bullish", "engulfing_bearish"}

    if min_confidence is None:
        min_confidence = 0.0
    if not isinstance(min_confidence, (int, float)) or isinstance(min_confidence, bool) or not math.isfinite(float(min_confidence)) or float(min_confidence) < 0 or float(min_confidence) > 1:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "min_confidence must be a number between 0 and 1")

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    if not any(isinstance(r, dict) and r.get("id") == instrument_id for r in instruments):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Instrument not found", instrument_id=instrument_id)

    cache = _load("market_data_cache.json")
    if not isinstance(cache, list):
        cache = []
    now = _now_utc()

    # ensure candles
    hist_row = None
    for r in cache:
        if isinstance(r, dict) and r.get("instrument_id") == instrument_id and r.get("data_type") == "historical_candles" and r.get("timeframe") == timeframe and r.get("status") == "fresh":
            hist_row = r
            break
    if hist_row is None:
        n = max_points
        base = 100.0
        candles = []
        for i in range(n):
            h = hashlib.sha256(f"{instrument_id}:{timeframe}:pat:{i}".encode("utf-8")).digest()
            delta = (h[0] - 128) / 1280.0
            op = base + delta
            hi = op + abs((h[1] - 128) / 384.0)
            lo = op - abs((h[2] - 128) / 384.0)
            cl = lo + (hi - lo) * (h[3] / 255.0)
            base = cl
            ts = now - datetime.timedelta(minutes=(n - 1 - i))
            candles.append({"t": _iso(ts), "open": op, "high": hi, "low": lo, "close": cl})
        now_iso = _iso(now)
        hist_row = {
            "id": _gen_id("grw_mdc"),
            "instrument_id": instrument_id,
            "data_type": "historical_candles",
            "timeframe": timeframe,
            "from_ts": from_ts,
            "to_ts": to_ts,
            "max_points": n,
            "derived_from_cache_id": None,
            "algorithm": None,
            "parameters": None,
            "as_of": now_iso,
            "ttl_seconds": 60,
            "status": "fresh",
            "payload": {"candles": candles},
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        cache.append(hist_row)
        _save("market_data_cache.json", cache)

    candles = (hist_row.get("payload") or {}).get("candles") if isinstance(hist_row.get("payload"), dict) else None
    if not isinstance(candles, list) or len(candles) < 5:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No candle data available", derived_from_cache_id=hist_row.get("id"))
    candles = candles[-max_points:]

    def _candle_parts(c):
        o, h, l, cl = float(c["open"]), float(c["high"]), float(c["low"]), float(c["close"])
        body = abs(cl - o)
        rng = max(1e-12, h - l)
        upper = h - max(o, cl)
        lower = min(o, cl) - l
        return o, h, l, cl, body, rng, upper, lower

    detected = []

    # Very lightweight deterministic heuristics; assign confidence in [0,1]
    for i in range(1, len(candles)):
        c = candles[i]
        p = candles[i - 1]
        if not (isinstance(c, dict) and isinstance(p, dict)):
            continue
        if not all(k in c for k in ("open", "high", "low", "close", "t")):
            continue
        if not all(k in p for k in ("open", "high", "low", "close", "t")):
            continue

        try:
            o, h, l, cl, body, rng, upper, lower = _candle_parts(c)
            po, ph, pl, pcl, pbody, prng, pupper, plower = _candle_parts(p)
        except Exception:
            continue

        bull = cl > o
        pbull = pcl > po

        def _add(name, conf, direction=None):
            if name not in wanted:
                return
            if conf < float(min_confidence):
                return
            detected.append({
                "pattern": name,
                "timestamp": c.get("t"),
                "confidence": float(max(0.0, min(1.0, conf))),
                "direction": direction
            })

        # doji: small body
        _add("doji", 1.0 - min(1.0, body / rng), None)

        # hammer / hanging_man
        if lower > body * 2 and upper <= body:
            _add("hammer", min(1.0, lower / rng), "bullish")
            _add("hanging_man", min(1.0, lower / rng), "bearish")

        # inverted hammer / shooting star
        if upper > body * 2 and lower <= body:
            _add("inverted_hammer", min(1.0, upper / rng), "bullish")
            _add("shooting_star", min(1.0, upper / rng), "bearish")

        # engulfing
        if bull and not pbull and cl >= po and o <= pcl:
            _add("engulfing_bullish", 0.8, "bullish")
        if (not bull) and pbull and o >= pcl and cl <= po:
            _add("engulfing_bearish", 0.8, "bearish")

        # harami
        if bull and not pbull and o >= pcl and cl <= po:
            _add("harami_bullish", 0.6, "bullish")
        if (not bull) and pbull and cl >= po and o <= pcl:
            _add("harami_bearish", 0.6, "bearish")

    result_payload = {
        "derived_from_cache_id": hist_row.get("id"),
        "patterns_scanned": sorted(list(wanted)),
        "min_confidence": float(min_confidence),
        "detections": detected,
        "as_of": _iso(now)
    }

    params = {"patterns": sorted(list(wanted)), "min_confidence": float(min_confidence), "max_points": max_points, "from_ts": from_ts, "to_ts": to_ts, "timeframe": timeframe}
    now_iso = _iso(now)
    ind_row = {
        "id": _gen_id("grw_mdc"),
        "instrument_id": instrument_id,
        "data_type": "indicator_result",
        "timeframe": timeframe,
        "from_ts": from_ts,
        "to_ts": to_ts,
        "max_points": max_points,
        "derived_from_cache_id": hist_row.get("id"),
        "algorithm": "candlestick_patterns",
        "parameters": params,
        "as_of": now_iso,
        "ttl_seconds": 60,
        "status": "fresh",
        "payload": result_payload,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    cache.append(ind_row)
    _save("market_data_cache.json", cache)

    _log("success")
    return {"instrument_id": instrument_id, "timeframe": timeframe, "result": result_payload, "cache_id": ind_row["id"]}

def get_instrument_import_job(id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # No auth collections were provided in schema; treat as ambient-authenticated.
    # Also no audit/usage collections provided; do not mutate core collections for reads.

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    jobs = _load("instrument_import_jobs.json")
    job = None
    for r in jobs:
        if isinstance(r, dict) and r.get("id") == id:
            job = r
            break
    if not job:
        return _err("NOT_FOUND", "Instrument import job not found", id=id)

    return {"instrument_import_job": job}

def cancel_instrument_import_job(id, reason=None, **_extra):
    import json, os, datetime, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    def _gen_id(prefix):
        raw = f"{prefix}:{_iso(_now_utc())}:{os.getpid()}:{time.time_ns()}:{random.random()}".encode("utf-8")
        return f"{prefix}_01{hashlib.sha256(raw).hexdigest()[:24].upper()}"
    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": _gen_id("grw_req"),
                "endpoint": "cancel_instrument_import_job",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(_now_utc()),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    try:
        if not isinstance(id, str) or not id.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        if reason is not None and (not isinstance(reason, str) or not reason.strip()):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "reason must be a non-empty string when provided", field="reason")

        jobs = _load("instrument_import_jobs.json")
        if not isinstance(jobs, list):
            jobs = []

        idx = None
        job = None
        for i, r in enumerate(jobs):
            if isinstance(r, dict) and r.get("id") == id:
                idx, job = i, r
                break
        if job is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Instrument import job not found", id=id)

        cur = job.get("status")
        # Business rule: refuse terminal
        terminal = ("completed", "failed", "cancelled")
        if cur in terminal:
            _log("error", "INVALID_TRANSITION")
            return _err(
                "INVALID_TRANSITION",
                "Cancellation refused by business rule: job is already in a terminal state (completed/failed/cancelled)",
                current_status=cur,
                id=id,
            )

        # Enforce lifecycle transitions from schema
        allowed = {
            "queued": ["downloading", "cancelled"],
            "downloading": ["parsing", "failed", "cancelled"],
            "parsing": ["indexing", "failed", "cancelled"],
            "indexing": ["completed", "failed", "cancelled"],
        }
        if "cancelled" not in allowed.get(cur, []):
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Status transition not allowed by lifecycle rules", current_status=cur, requested_status="cancelled", id=id)

        now = _now_utc()
        job["status"] = "cancelled"
        job["updated_at"] = _iso(now)
        job["finished_at"] = _iso(now)
        if reason is not None:
            job["error_message"] = reason.strip()

        jobs[idx] = job
        _save("instrument_import_jobs.json", jobs)

        _log("success", None, {"id": id, "from": cur, "to": "cancelled"})
        return {"job": job}
    except Exception as e:
        _log("error", "FAILED", {"exception": str(e)})
        return _err("FAILED", "Internal error")

def get_auth_context(include_rate_limits=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0344000" if __import__("os").path.isdir("./environment_mix/0344000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if include_rate_limits is not None and not isinstance(include_rate_limits, bool):
        return _err("VALIDATION_ERROR", "include_rate_limits must be a boolean when provided", field="include_rate_limits")

    # No explicit auth schema/collections were provided, and authentication is ambient.
    # Therefore, we can only return a minimal context indicating ambient authentication.
    # Rate-limit/quota consumption is "when available"; no usage/audit store exists in given schema.
    ctx = {
        "authenticated": True,
        "credential": {
            "type": "ambient",
            "id": None,
            "display": "ambient",
        },
        "scopes": ["*"],
        "server_time": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    }

    if include_rate_limits:
        ctx["rate_limits"] = {
            "available": False,
            "reason": "No request-log/usage collections available in datastore schema to compute consumption.",
        }

    return {"auth_context": ctx}
